  # (c) dry-run não escreve nada
  d="$(mktemp -d)"; bash "${helper}" xproj --dir "${d}" --dry-run >/dev/null 2>&1
  if [ "$(find "${d}/.claude" -type f 2>/dev/null | wc -l)" -eq 0 ]; then record_pass "bootstrap-vertical: dry-run não escreve"
