  mkdir -p "${d}/bc" "${d}/tc" "${d}/cc"
  today="$(date +%F)"; old="$(date -d '3 years ago' +%F 2>/dev/null || echo 2000-01-01)"
  printf -- '---\ndate: %s\n---\n# doc atual\n' "${today}" > "${d}/bc/a.md"
  printf '# doc velho\n\n**Última Atualização:** %s\n' "${old}" > "${d}/tc/b.md"
