}
_family run_kb_vendored_link_selftests

# Modo selftest-lanes — as FAIXAS da bancada (D_BANCADA_FAIXAS_E_MAPA, 2026-09-03): --list/--map/--families/
# --affected (mapa derivado + failsafe)/--jobs (pai agrega trailers; worker sem soma = FALHA). Inclui a guarda
# que teria pego a família-fantasma `vendor_pin` (invocação dentro do próprio corpo por 44 dias): toda família
# DEFINIDA tem de aparecer no --list.
run_selftest_lanes_selftests() {
  local sut="${REPO_ROOT}/.claude/validation/lint-selftest.sh"
  if [ ! -f "${sut}" ]; then record_fail "selftest-lanes" "bancada ausente: ${sut}"; return; fi
  local out rc n defs
  # (a) --list: só nomes, ≥100, inclui fixtures e vendor_pin
  out="$(bash "${sut}" --list 2>/dev/null || true)"
  n="$(printf '%s\n' "${out}" | grep -c .)"
  if [ "${n}" -ge 100 ] && ! grep -qvE '^[a-z0-9_]+$' <<< "${out}" \
     && grep -qx fixtures <<< "${out}" && grep -qx vendor_pin <<< "${out}"; then
    record_pass "selftest-lanes: (a) --list = ${n} nomes puros, com fixtures e vendor_pin"
  else record_fail "selftest-lanes: (a) --list" "n=${n}; linhas não-nome: $(printf '%s\n' "${out}" | grep -vE '^[a-z0-9_]+$' | head -2 | tr '\n' '|')"; fi
  # (b) GUARDA DA FANTASMA: toda família definida é invocada no top-level (definições == --list)
  defs="$(grep -cE '^run_[a-z0-9_]+_selftests\(\) \{' "${sut}")"
  if [ "${defs}" -eq "${n}" ]; then
    record_pass "selftest-lanes: (b) ${defs} famílias definidas = ${n} invocadas (nenhuma fantasma)"
  else record_fail "selftest-lanes: (b) família fantasma" "definidas=${defs} invocadas=${n}: $(diff <(grep -oE '^run_[a-z0-9_]+_selftests\(\)' "${sut}" | sed -E 's/^run_(.*)_selftests\(\)/\1/' | sort) <(printf '%s\n' "${out}" | sort) | grep '^[<>]' | sed -n '1,3p' | tr '\n' ' ')"; fi
  # (c) --families roda SÓ a família pedida (ladder_integrity = 1 caso)
  out="$(bash "${sut}" --families ladder_integrity 2>&1 || true)"
  n="$(printf '%s\n' "${out}" | grep -c '^  ✓' || true)"
  if [ "${n}" -eq 1 ] && grep -q '^OK ✓' <<< "${out}"; then
    record_pass "selftest-lanes: (c) --families ladder_integrity ⇒ 1 ✓ e OK"
  else record_fail "selftest-lanes: (c) --families" "✓=${n}; $(printf '%s\n' "${out}" | tail -1)"; fi
  # (d) --map cobre toda família listada
  out="$(bash "${sut}" --map 2>/dev/null || true)"
  local missing; missing="$(comm -23 <(bash "${sut}" --list | sort -u) <(printf '%s\n' "${out}" | cut -f1 | sort -u) | sed -n '1,3p' | tr '\n' ' ')"
  if [ -n "${out}" ] && [ -z "${missing}" ]; then record_pass "selftest-lanes: (d) --map cobre todas as famílias listadas"
  else record_fail "selftest-lanes: (d) --map" "sem entrada: ${missing:-<mapa vazio>}"; fi
  # (e) --affected por helper conhecido seleciona a família dele e NÃO as outras
  out="$(bash "${sut}" --affected .claude/validation/ladder-integrity-check.sh --dry-run 2>&1 || true)"
  if grep -q '^dry-run: famílias=.*ladder_integrity' <<< "${out}"&& ! grep -q 'vendor_pin' <<< "${out}"; then
    record_pass "selftest-lanes: (e) --affected helper ⇒ seleciona ladder_integrity, não vendor_pin"
  else record_fail "selftest-lanes: (e) --affected" "$(printf '%s\n' "${out}" | tail -1 | cut -c1-120)"; fi
  # (f) failsafe: infraestrutura da bancada ⇒ TUDO
  out="$(bash "${sut}" --affected .claude/validation/lint-artifacts.sh --dry-run 2>&1 || true)"
  if grep -q 'famílias=<todas>' <<< "${out}"&& grep -q 'failsafe' <<< "${out}"; then
    record_pass "selftest-lanes: (f) failsafe: lint-artifacts.sh ⇒ todas"
  else record_fail "selftest-lanes: (f) failsafe infra" "$(printf '%s\n' "${out}" | tail -1 | cut -c1-120)"; fi
  # (g) failsafe: arquivo do domínio citado por ninguém ⇒ TUDO (recusa no incerto)
  out="$(bash "${sut}" --affected .claude/validation/zz-nao-existe.sh --dry-run 2>&1 || true)"
  if grep -q 'famílias=<todas>' <<< "${out}"&& grep -q 'nenhuma família' <<< "${out}"; then
    record_pass "selftest-lanes: (g) failsafe: arquivo desconhecido no domínio ⇒ todas"
  else record_fail "selftest-lanes: (g) failsafe desconhecido" "$(printf '%s\n' "${out}" | tail -1 | cut -c1-120)"; fi
  # (h)(i)(j) cópia hermética com famílias sintéticas (REPO_ROOT da cópia = sandbox)
  # o top-level da bancada copia .claude/docs/CLAUDE.md p/ o sandbox e lê inventory.sh --env (grep vazio sob
  # pipefail aborta): a cópia leva .claude/ e docs/ inteiros (33 MB) — REPO_ROOT da cópia = este sandbox
  local d; d="$(mktemp -d)"
  cp -a "${REPO_ROOT}/.claude" "${d}/.claude"; cp -a "${REPO_ROOT}/docs" "${d}/docs"; cp -a "${REPO_ROOT}/CLAUDE.md" "${d}/CLAUDE.md"
  python3 - "${d}/.claude/validation/lint-selftest.sh" <<'PYI'
import sys; p=sys.argv[1]; s=open(p).read()
i=s.rindex('echo "=== Sumário do auto-teste de guardas ==="')
# insere antes do bloco list/child (que precede o cabeçalho do sumário)
k=s.rfind('if [ "${SELFTEST_LIST}" = "1" ]; then SUMMARY_PRINTED=1; exit 0; fi', 0, i)
syn='run_zz_ok_selftests() { record_pass "zz ok"; }\n_family run_zz_ok_selftests\nrun_zz_ok2_selftests() { record_pass "zz ok2"; }\n_family run_zz_ok2_selftests\nrun_zz_abort_selftests() { exit 3; }\n_family run_zz_abort_selftests\n'
s=s[:k]+syn+s[k:]; open(p,"w").write(s)
PYI
  local copy="${d}/.claude/validation/lint-selftest.sh"
  out="$(bash "${copy}" --families zz_ok,zz_ok2 --jobs 2 2>&1)" && rc=0 || rc=$?
  if [ "${rc}" -eq 0 ] && grep -q 'Passaram : 2' <<< "${out}"&& grep -q 'faixa paralela: 2 famílias / 2 workers' <<< "${out}"; then
    record_pass "selftest-lanes: (h) --jobs 2 agrega 2 workers ⇒ Passaram 2, exit 0"
  else record_fail "selftest-lanes: (h) --jobs agrega" "rc=${rc}; $(printf '%s\n' "${out}" | grep -E 'Passaram|faixa' | tr '\n' '|' | cut -c1-140)"; fi
  out="$(bash "${copy}" --families zz_ok,zz_abort --jobs 2 2>&1)" && rc=0 || rc=$?
  if [ "${rc}" -eq 1 ] && grep -q 'ABORTOU sem somar' <<< "${out}"&& grep -q 'zz_abort reivindicada e NÃO concluída' <<< "${out}"&& ! grep -q '^OK ✓' <<< "${out}"; then
    record_pass "selftest-lanes: (i) worker que aborta ⇒ FALHA no pai (exit 1): sem trailer + família reivindicada-e-não-concluída nomeada"
  else record_fail "selftest-lanes: (i) worker abortado" "rc=${rc}; $(printf '%s\n' "${out}" | grep -E 'ABORTOU|Passaram|^OK|FALHOU' | tr '\n' '|' | cut -c1-160)"; fi
  out="$(bash "${copy}" --families zz_ok --child 2>&1 || true)"
  if grep -qx '#ONION_SELFTEST_COUNTS 1 0 0' <<< "${out}"; then
    record_pass "selftest-lanes: (j) --child imprime o trailer de soma (1 0 0)"
  else record_fail "selftest-lanes: (j) trailer" "$(printf '%s\n' "${out}" | tail -1 | cut -c1-100)"; fi
  # (k) default = serial, tudo (comportamento antigo preservado)
  out="$(bash "${copy}" --dry-run 2>&1 || true)"
  if grep -qx 'dry-run: famílias=<todas> jobs=1' <<< "${out}"; then
    record_pass "selftest-lanes: (k) sem argumento = serial e todas as famílias (compat)"
  else record_fail "selftest-lanes: (k) default" "$(printf '%s\n' "${out}" | tail -1 | cut -c1-100)"; fi
  # (l) VACUIDADE: seleção que não exerce guarda nenhuma NÃO é verde
  out="$(bash "${copy}" --families zz_nao_existe 2>&1)" && rc=0 || rc=$?
  if [ "${rc}" -eq 1 ] && grep -q 'NENHUMA guarda foi exercida' <<< "${out}"; then
    record_pass "selftest-lanes: (l) --families inexistente ⇒ FALHOU por vacuidade (0 guardas ≠ verde)"
  else record_fail "selftest-lanes: (l) vacuidade" "rc=${rc}; $(printf '%s\n' "${out}" | tail -1 | cut -c1-100)"; fi
  # (m) SHARD do manifest: 4 fixtures reais no manifest da cópia; 2 workers ⇒ cada linha exatamente uma vez
  local mf="${d}/.claude/validation/fixtures/manifest.tsv"
  { grep -E '^kind' "${REPO_ROOT}/.claude/validation/fixtures/manifest.tsv"; grep -E '^lint' "${REPO_ROOT}/.claude/validation/fixtures/manifest.tsv" | sed -n '1,4p'; } > "${mf}"   # sed drena: `| head` dava EPIPE ao grep (exit 2) e matou o worker 0 no CI (2 cores)
  out="$(bash "${copy}" --families fixtures --jobs 2 2>&1)" && rc=0 || rc=$?
  n="$(printf '%s\n' "${out}" | grep -c '^  ✓' || true)"
  if [ "${rc}" -eq 0 ] && [ "${n}" -eq 4 ] && grep -q 'Passaram : 4' <<< "${out}"; then
    record_pass "selftest-lanes: (m) fixtures fatiada em 2 workers ⇒ 4 casos, cada linha do manifest uma vez"
  else record_fail "selftest-lanes: (m) shard" "rc=${rc} ✓=${n}; $(printf '%s\n' "${out}" | grep -E 'Passaram|ABORTOU' | tr '\n' '|' | cut -c1-120)"; fi
  out="$(ONION_SELFTEST_SHARD=1/2 bash "${copy}" --families fixtures --child 2>&1 || true)"
  if grep -qx '#ONION_SELFTEST_COUNTS 2 0 0' <<< "${out}"; then
    record_pass "selftest-lanes: (n) ONION_SELFTEST_SHARD=1/2 ⇒ metade do manifest (2 de 4)"
  else record_fail "selftest-lanes: (n) shard child" "$(printf '%s\n' "${out}" | tail -1 | cut -c1-100)"; fi

  # ── (o)-(q) --report: o relatório legível por máquina não pode custar a integridade da suíte ──
  #
  #  A pergunta que estes três casos respondem NÃO é "o TSV sai?" — é "instrumentar a bancada
  #  mudou a bancada?". Esta suíte já morreu calada uma vez e já deu falso ✗ por EPIPE em 337
  #  sítios; escrita de arquivo aqui dentro é exatamente a classe de mudança que reintroduz isso.
  local rep="${d}/rep.tsv"
  # (o) caminho RELATIVO reprova: famílias fazem `cd` em sandbox e o arquivo cairia em lugar
  #     imprevisível — o mesmo modo de falha que já custou a esta suíte um `_lib_beside` inteiro.
  out="$(bash "${copy}" --families ladder_integrity --report rel.tsv 2>&1)" && rc=0 || rc=$?
  if [ "${rc}" -eq 2 ] && grep -q 'caminho ABSOLUTO' <<< "${out}"; then
    record_pass "selftest-lanes: (o) --report com caminho relativo ⇒ rc=2, e diz por quê"
  else record_fail "selftest-lanes: (o) --report relativo" "rc=${rc}; $(printf '%s\n' "${out}" | tail -1 | cut -c1-100)"; fi
  # (p) A CONDIÇÃO DE ACEITE: a flag não altera a contagem. Sem este caso, `--report` poderia
  #     engolir um ✗ e ninguém saberia — o relatório sairia bonito sobre uma suíte menor.
  local sem com
  sem="$(bash "${copy}" --families ladder_integrity 2>&1 | grep -E '^  (Passaram|Pularam|Falharam)')"
  com="$(bash "${copy}" --families ladder_integrity --report "${rep}" 2>&1 | grep -E '^  (Passaram|Pularam|Falharam)')"
  if [ -n "${sem}" ] && [ "${sem}" = "${com}" ]; then
    record_pass "selftest-lanes: (p) --report NÃO altera a contagem (mesma soma com e sem a flag)"
  else record_fail "selftest-lanes: (p) --report altera contagem" "sem=[$(tr '\n' '|' <<< "${sem}")] com=[$(tr '\n' '|' <<< "${com}")]"; fi
  # (q) o TOTAL do TSV é a SOMA das linhas de família — um relatório cuja aritmética não fecha é
  #     pior que relatório nenhum: ele parece medição.
  if [ -f "${rep}" ] && head -1 "${rep}" | grep -q '^familia'; then
    local somap totp
    somap="$(awk -F'\t' '$1!="familia" && $1!="TOTAL" && $1!="FAIL" && $1!="SKIP" {s+=$2} END{print s+0}' "${rep}")"
    totp="$(awk -F'\t' '$1=="TOTAL"{print $2+0}' "${rep}")"
    if [ -n "${totp}" ] && [ "${somap}" = "${totp}" ]; then
      record_pass "selftest-lanes: (q) TOTAL do --report = soma das famílias (${totp})"
    else record_fail "selftest-lanes: (q) aritmética do --report" "soma das famílias=${somap} TOTAL=${totp:-<ausente>}"; fi
  else record_fail "selftest-lanes: (q) --report não produziu TSV com cabeçalho" "arquivo=${rep}"; fi

  rm -rf "${d}"
}
_family run_selftest_lanes_selftests

# ── testing_state — O PAINEL (ONDA 0.7) ──────────────────────────────────────────────────────
#
#  As cinco defesas contra virar o SEGUNDO painel inventado não são cerimônia: o cadáver do
#  primeiro está no git (`Coverage: 85% · Mutation: 74%`, zero produtores, meses no ar). Cada
#  caso aqui é a fixture de uma delas.
run_testing_state_selftests() {
  local sut="${REPO_ROOT}/.claude/validation/testing-state.sh"
  if [ ! -f "${sut}" ]; then record_skip "testing-state: gerador ausente (SUT não exercido)"; return; fi
  local out rc

  # (a) DEFESA 1 — toda célula impressa carrega o COMANDO que a produz. Asserção MECÂNICA, não
  #     visual: cada linha de tabela com valor em negrito tem de ter uma terceira coluna com
  #     crase. É o que teria impedido `Coverage: 85%` de nascer — ninguém escreve o comando de
  #     um número que não mediu.
  out="$(bash "${sut}" --markdown 2>&1)" || { record_fail "testing-state: (a) gerador" "não rodou: ${out}"; return; }
  local sem_produtor
  sem_produtor="$(grep -E '^\| .* \| \*\*[^*]+\*\* \|' <<< "${out}" | grep -vc '`' || true)"
  if [ "${sem_produtor}" = "0" ]; then
    record_pass "testing-state: (a) toda célula com número carrega o COMANDO ao lado (defesa 1)"
  else record_fail "testing-state: (a) célula sem produtor" "${sem_produtor} célula(s) com número e SEM comando — é assim que o painel inventado nasce"; fi

  # (b) DEFESA 3 — o terceiro desfecho existe no painel real. Hoje há seções genuinamente não
  #     medidas (flaky com poucas execuções, cobertura de código inexistente); se um dia
  #     nenhuma `⊘` aparecer, ou o repo mede tudo, ou o painel voltou a inventar.
  if grep -q '⊘ \*\*NÃO MEDIDO\*\*' <<< "${out}"; then
    record_pass "testing-state: (b) o painel imprime ⊘ NÃO MEDIDO onde não mediu (defesa 3)"
  else record_fail "testing-state: (b) terceiro desfecho" "nenhum ⊘ no painel — ou o repo passou a medir TUDO, ou voltou a inventar"; fi

  # (c) DEFESA 5 — o painel declara a idade da medição SEM imprimir "hoje". Artefato catracado
  #     que carrega a data corrente produz uma HARD por dia sem que nada aconteça, e guarda que
  #     grita sem motivo ensina a ser ignorada. Este caso trava a decisão: sem ele, alguém
  #     "conserta" a idade pondo `date +%F` no gerador e a catraca vira ruído diário.
  local hoje; hoje="$(date +%F)"
  if grep -q 'última medição:' <<< "${out}" && ! grep -q "hoje.*${hoje}\|${hoje}.*hoje" <<< "${out}"; then
    record_pass "testing-state: (c) declara a data da MEDIÇÃO e NÃO imprime 'hoje' (defesa 5 sem catraca-ruído)"
  else record_fail "testing-state: (c) idade" "o painel imprime a data corrente — a catraca passaria a reprovar todo dia por nada"; fi

  # (d) DEFESA 4 (MUT) — zero produtor vivo derruba o gerador. Painel vazio E catracado é pior
  #     que painel nenhum: vira verde por vacuidade, o modo de falha que esta casa mais paga.
  local mut; mut="$(mktemp -d)"
  cp "${sut}" "${mut}/m.sh"
  sed -i 's/^VIVOS=0$/VIVOS=0; _FORCA_VAZIO=1/' "${mut}/m.sh"
  sed -i 's|^if HARNESS_ENV=.*|if [ -z "${_FORCA_VAZIO:-}" ] \&\& HARNESS_ENV="$(bash "${SCRIPT_DIR}/harness-inventory.sh" --env 2>/dev/null)"; then|' "${mut}/m.sh"
  sed -i 's|^if R56_ENV=.*|if [ -z "${_FORCA_VAZIO:-}" ] \&\& R56_ENV="$(bash "${SCRIPT_DIR}/review-ledger.sh" --env 2>/dev/null)"; then|' "${mut}/m.sh"
  sed -i 's|^if \[ -f "${LEDGER}" \] && \[ -s "${LEDGER}" \]; then|if [ -z "${_FORCA_VAZIO:-}" ] \&\& [ -f "${LEDGER}" ] \&\& [ -s "${LEDGER}" ]; then|' "${mut}/m.sh"
  if grep -q '_FORCA_VAZIO=1' "${mut}/m.sh"; then
    rc=0; out="$(bash "${mut}/m.sh" --markdown 2>&1)" || rc=$?
    if [ "${rc}" -eq 2 ] && grep -qi 'vacui' <<< "${out}"; then
      record_pass "testing-state: (d) zero produtor vivo → exit 2 nomeando VACUIDADE (defesa 4), não painel vazio"
    else record_fail "testing-state: (d) vacuidade" "esperava rc=2 nomeando vacuidade; rc=${rc} out=$(head -c 200 <<< "${out}")"; fi
  else
    record_fail "testing-state: (d) vacuidade" "a mutação NÃO foi aplicada — o teste não prova nada"
  fi
  rm -rf "${mut}"

  # (e) arg desconhecido → exit 2 (não cai no default calado).
  rc=0; bash "${sut}" --nao-existe >/dev/null 2>&1 || rc=$?
  if [ "${rc}" -eq 2 ]; then
    record_pass "testing-state: (e) arg desconhecido → exit 2"
  else record_fail "testing-state: (e) arg" "esperava 2, veio ${rc}"; fi

  # (g) ⭐ A REGRA 81 É EXERCITADA PELO CAMINHO QUE A PRODUÇÃO USA — e este caso existe porque
  #     ela NÃO ERA. A passada adversarial do PR provou por mutação: desligou `check_testing_state_drift`
  #     inteira (`if false`) e `--families testing_state` deu 6 PASS / 0 FAIL. A guarda HARD que esta
  #     onda existe para entregar podia sumir sem nenhum caso reclamar.
  #
  #     DUAS causas somadas, ambas minhas: (1) eu adicionei `[ -n "${ONLY_PATH}" ] && return 0` para
  #     curar performance, e TODA fixture da bancada chama o lint com `--only` — a regra virou
  #     estruturalmente inalcançável por esse caminho; (2) as duas famílias que rodam o lint COMPLETO
  #     carimbam `role: adopted`, o que dispara o outro early-return (`IS_DERIVED`). Somadas, zero
  #     caminhos de teste chegavam nela.
  #
  #     Por isso este caso monta um sandbox SEM stamp (IS_DERIVED=0) e roda o lint COMPLETO (sem
  #     `--only`): é o único par de condições em que a guarda executa. E prova por COMPORTAMENTO —
  #     original acusa, mutante cala —, não por existência de string.
  local mut81 sb81 rc81 out81 hit81_orig hit81_mut
  mut81="$(mktemp -d)"; sb81="$(mktemp -d)"
  cp "${SCRIPT_DIR}/lint-artifacts.sh" "${mut81}/m.sh"
  sed -i 's|^     ! diff -q "${tracked}" "${tmp}" >/dev/null 2>&1; then|     false; then|g' "${mut81}/m.sh"
  local n81; n81="$(grep -c '^     false; then' "${mut81}/m.sh" || true)"
  mkdir -p "${sb81}/.claude/validation" "${sb81}/docs/onion/metrics"
  cp -a "${SCRIPT_DIR}"/*.sh "${sb81}/.claude/validation/" 2>/dev/null || true
  cp -a "${SCRIPT_DIR}/fixtures" "${sb81}/.claude/validation/fixtures" 2>/dev/null || true
  cp "${mut81}/m.sh" "${sb81}/.claude/validation/m.sh"
  ( cd "${sb81}" && git init -q && git add -A >/dev/null 2>&1 ) 2>/dev/null
  # painel gerado e DEPOIS adulterado à mão — o cenário exato que a REGRA 81 existe para pegar
  bash "${SCRIPT_DIR}/testing-state.sh" --markdown > "${sb81}/docs/onion/testing-state.md" 2>/dev/null || true
  printf 'LINHA INJETADA A MAO\n' >> "${sb81}/docs/onion/testing-state.md"
  ( cd "${sb81}" && git add -A >/dev/null 2>&1 ) 2>/dev/null
  out81="$( cd "${sb81}" && bash .claude/validation/lint-artifacts.sh 2>&1 )" || true
  hit81_orig="$(grep -c 'REGRA 81' <<< "${out81}" || true)"
  out81="$( cd "${sb81}" && bash .claude/validation/m.sh 2>&1 )" || true
  hit81_mut="$(grep -c 'REGRA 81' <<< "${out81}" || true)"
  if [ "${n81}" -ge 2 ] && [ "${hit81_orig}" -ge 1 ] && [ "${hit81_mut}" -eq 0 ]; then
    record_pass "testing-state: (g) a REGRA 81 é ALCANÇADA no lint completo sem stamp, e some no mutante — guarda load-bearing, não inalcançável"
  else record_fail "testing-state: (g) alcance da REGRA 81" "sítios mutados=${n81} (esperava >=2); original acusou=${hit81_orig} (esperava >=1); mutante acusou=${hit81_mut} (esperava 0). Se orig=0, a regra voltou a ser inalcançável pelo caminho de teste — que foi o defeito achado no PR."; fi
  rm -rf "${mut81}" "${sb81}"

  # (f) O PAINEL DECLARA O QUE NÃO MEDE. Sem esta seção, a ausência de uma linha sobre cobertura
  #     de código é lida como "não é problema" em vez de "não existe suíte". Ausência silenciosa
  #     é a forma mais barata de mentir num painel.
  out="$(bash "${sut}" --markdown 2>&1)"
  if grep -q 'NÃO mede' <<< "${out}" && grep -q 'Cobertura de código' <<< "${out}"; then
    record_pass "testing-state: (f) o painel declara o que NÃO mede (ausência nomeada, não silenciosa)"
  else record_fail "testing-state: (f) fronteiras" "sem a seção de não-medidos, a ausência vira 'sem problema'"; fi
}

# ── ci_evidence — o SUMÁRIO do CI (ONDA 0.4) ─────────────────────────────────────────────────
#
#  O gerador do `$GITHUB_STEP_SUMMARY` virou SCRIPT justamente para caber aqui. Shell embutido
#  em YAML é a única peça do gate que nenhuma guarda exercita: não roda local, não entra na
#  bancada, e só se descobre que quebrou no dia em que alguém precisa dele para entender uma
#  falha — e encontra o bloco vazio.
run_ci_evidence_selftests() {
  local sut="${REPO_ROOT}/ops/testing/selftest-summary.sh"
  if [ ! -f "${sut}" ]; then record_skip "ci-evidence: gerador de sumário ausente (SUT não exercido)"; return; fi
  local d out rc
  d="$(mktemp -d)"

  # (a) VERDE: a tabela sai com os números do relatório, e nenhum deles é digitado.
  printf 'familia\tpass\tfail\tskip\tsegundos\nalfa\t7\t0\t0\t3\nbeta\t5\t0\t0\t9\nTOTAL\t12\t0\t0\t12\n' > "${d}/ok.tsv"
  rc=0; out="$(bash "${sut}" --report "${d}/ok.tsv" 2>&1)" || rc=$?
  if [ "${rc}" -eq 0 ] && grep -q '✅' <<< "${out}" && grep -q '| \*\*12\*\* |' <<< "${out}" \
     && grep -q 'Nenhuma família falhou' <<< "${out}"; then
    record_pass "ci-evidence: (a) relatório verde → tabela com a soma e o ícone ✅"
  else record_fail "ci-evidence: (a) verde" "rc=${rc} out=${out}"; fi

  # (b) VERMELHO: o sumário tem de NOMEAR quem falhou. Um sumário que só diz "2 falhas" obriga
  #     quem lê a abrir o log — e o log é justamente o que expira.
  printf 'familia\tpass\tfail\tskip\tsegundos\nalfa\t7\t0\t0\t3\nbeta\t3\t2\t0\t9\nTOTAL\t10\t2\t0\t12\n' > "${d}/red.tsv"
  rc=0; out="$(bash "${sut}" --report "${d}/red.tsv" 2>&1)" || rc=$?
  if [ "${rc}" -eq 0 ] && grep -q '❌' <<< "${out}" && grep -q '`beta` — 2 falha' <<< "${out}"; then
    record_pass "ci-evidence: (b) falha → o sumário NOMEIA a família (não obriga a abrir o log que expira)"
  else record_fail "ci-evidence: (b) vermelho" "rc=${rc} out=${out}"; fi

  # (c) ⊘ NÃO MEDIDO — o caso que motivou o script. Relatório ausente é a assinatura da bancada
  #     que morreu antes da soma; imprimir "0 falhas" aqui seria o painel inventado, no CI.
  rc=0; out="$(bash "${sut}" --report "${d}/nao-existe.tsv" 2>&1)" || rc=$?
  if [ "${rc}" -eq 0 ] && grep -q '⊘' <<< "${out}" && grep -q 'NÃO MEDIDO' <<< "${out}" \
     && ! grep -qE '\| \*\*0\*\* \|' <<< "${out}"; then
    record_pass "ci-evidence: (c) relatório ausente → ⊘ NÃO MEDIDO e NENHUM zero impresso"
  else record_fail "ci-evidence: (c) ausente" "rc=${rc} out=${out}"; fi

  # (d) relatório SEM `TOTAL` → mesmo tratamento, com a suspeita NOMEADA (abortou antes da soma).
  printf 'familia\tpass\tfail\tskip\tsegundos\nalfa\t7\t0\t0\t3\n' > "${d}/semtotal.tsv"
  rc=0; out="$(bash "${sut}" --report "${d}/semtotal.tsv" 2>&1)" || rc=$?
  if [ "${rc}" -eq 0 ] && grep -q 'abortou antes da soma' <<< "${out}"; then
    record_pass "ci-evidence: (d) relatório sem TOTAL → ⊘ nomeando 'abortou antes da soma'"
  else record_fail "ci-evidence: (d) sem TOTAL" "rc=${rc} out=${out}"; fi

  # (e) A SOMA QUE NÃO FECHA é DENUNCIADA no próprio sumário. Sem isto, um relatório truncado
  #     produziria uma tabela bonita com um total que nenhuma parte sustenta.
  printf 'familia\tpass\tfail\tskip\tsegundos\nalfa\t7\t0\t0\t3\nTOTAL\t999\t0\t0\t3\n' > "${d}/naofecha.tsv"
  rc=0; out="$(bash "${sut}" --report "${d}/naofecha.tsv" 2>&1)" || rc=$?
  if [ "${rc}" -eq 0 ] && grep -q 'A SOMA NÃO FECHA' <<< "${out}" && grep -q '999' <<< "${out}"; then
    record_pass "ci-evidence: (e) TOTAL que não bate com as partes → o sumário DENUNCIA no próprio bloco"
  else record_fail "ci-evidence: (e) soma" "rc=${rc} out=${out}"; fi

  # (f) ELE REPORTA, NÃO JULGA. Mesmo com falhas, sai 0: o veredito é do passo da bancada. Dois
  #     juízes para o mesmo fato criam o dia em que discordam e ninguém sabe qual vale.
  rc=0; bash "${sut}" --report "${d}/red.tsv" >/dev/null 2>&1 || rc=$?
  if [ "${rc}" -eq 0 ]; then
    record_pass "ci-evidence: (f) sumário com falhas ainda sai 0 — ele REPORTA, quem julga é a bancada"
  else record_fail "ci-evidence: (f) fronteira" "saiu ${rc} — o gerador estaria julgando o build junto com a bancada"; fi

  # (g2) O SUMÁRIO DO LINT exige PROVA DE TÉRMINO. Log truncado — a assinatura de lint abortado
  #      por OOM/SIGPIPE/worker morto, os três já medidos aqui — tem zero `VIOLATION` e zero bloco
  #      de sumário. A versão embutida no YAML contava esse zero e imprimia ✅: VERDE SOBRE
  #      EXECUÇÃO ABORTADA, no artefato que existe para contar a verdade do gate.
  # ⚠️ A ÂNCORA DO VEREDITO É O CABEÇALHO (`^## ✅`), não o caractere solto. A 1ª versão desta
  #    asserção procurava `✅` em QUALQUER lugar da saída e reprovou — corretamente, mas pelo motivo
  #    errado: o ⊘ carrega a frase `um sumário que imprimisse ✅ aqui seria verde sobre execução
  #    abortada`, e o caractere está na PROSA DE AVISO. Asserção que casa o símbolo em vez da
  #    POSIÇÃO onde ele significa veredito proíbe o texto de explicar a si mesmo.
  local sutl="${REPO_ROOT}/ops/testing/lint-summary.sh"
  if [ -f "${sutl}" ]; then
    local dl; dl="$(mktemp -d)"
    printf 'VIOLATION: x: REGRA 1 algo\n=== Sumário ===\n  Violações HARD : 2\n  Violações SOFT : 5\n' > "${dl}/cheio.log"
    printf 'VIOLATION: x: REGRA 1 algo\n' > "${dl}/truncado.log"
    printf '=== Sumário ===\n  Violações HARD : 0\n  Violações SOFT : 3\n' > "${dl}/verde.log"
    local o_cheio o_trunc o_verde
    o_cheio="$(bash "${sutl}" --log "${dl}/cheio.log" 2>&1)"
    o_trunc="$(bash "${sutl}" --log "${dl}/truncado.log" 2>&1)"
    o_verde="$(bash "${sutl}" --log "${dl}/verde.log" 2>&1)"
    if grep -q '❌' <<< "${o_cheio}" && grep -q '| \*\*2\*\* |' <<< "${o_cheio}" \
       && grep -q '⊘' <<< "${o_trunc}" && grep -q 'abortou antes de somar' <<< "${o_trunc}" \
       && ! grep -q '^## ✅' <<< "${o_trunc}" \
       && grep -q '✅' <<< "${o_verde}"; then
      record_pass "ci-evidence: (g2) log truncado → ⊘ NÃO MEDIDO (nunca ✅); log com bloco de término → veredito real"
    else record_fail "ci-evidence: (g2) prova de término" "truncado devia dar ⊘ e nunca ✅ — se deu verde, voltou a contar zero de log abortado como zero de violação"; fi
    # (g3) formato mudou: bloco existe mas o campo não parseia ⇒ também é ⊘, não zero.
    printf '=== Sumário ===\n  Violacoes HARD = dois\n' > "${dl}/formato.log"
    if grep -q '⊘' <<< "$(bash "${sutl}" --log "${dl}/formato.log" 2>&1)"; then
      record_pass "ci-evidence: (g3) bloco presente mas campo ilegível → ⊘ (não inventa número de formato desconhecido)"
    else record_fail "ci-evidence: (g3) formato" "inventou veredito sobre um formato que não reconhece"; fi
    rm -rf "${dl}"
  else
    record_fail "ci-evidence: (g2) prova de término" "ops/testing/lint-summary.sh ausente — o workflow o invoca"
  fi

  # (g) arg desconhecido → exit 2 (não cai num default calado).
  rc=0; bash "${sut}" --nao-existe >/dev/null 2>&1 || rc=$?
  if [ "${rc}" -eq 2 ]; then
    record_pass "ci-evidence: (g) arg desconhecido → exit 2"
  else record_fail "ci-evidence: (g) arg" "esperava 2, veio ${rc}"; fi

  # (h) O WORKFLOW CHAMA ESTE SCRIPT DE VERDADE. Sem esta asserção, o gerador poderia estar
  #     perfeito e desligado — que é a forma mais cara de guarda: passa na bancada e não roda.
  local wf="${REPO_ROOT}/.github/workflows/onion-selftest.yml"
  if [ -f "${wf}" ] && grep -q 'ops/testing/selftest-summary.sh' "${wf}" \
     && grep -q 'GITHUB_STEP_SUMMARY' "${wf}" && grep -q 'upload-artifact' "${wf}"; then
    record_pass "ci-evidence: (h) o workflow da bancada de fato INVOCA o gerador, escreve no STEP_SUMMARY e sobe artefato"
  else record_fail "ci-evidence: (h) wire-in" "o gerador existe mas o workflow não o chama — guarda perfeita e desligada"; fi

  # (i) `if: always()` nos passos de evidência. É o ponto inteiro: a evidência que importa é a
  #     do job que FALHOU. Sem always, o CI só guarda prova de sucesso.
  if [ -f "${wf}" ] && [ "$(grep -c 'if: always()' "${wf}")" -ge 2 ]; then
    record_pass "ci-evidence: (i) os passos de evidência têm 'if: always()' — o CI guarda prova de FALHA, não só de sucesso"
  else record_fail "ci-evidence: (i) always" "menos de 2 'if: always()' no workflow — a evidência sumiria justo quando é necessária"; fi

  rm -rf "${d}"
}

# ── selftest_series — a SÉRIE HISTÓRICA da bancada (ONDA 0.6) ────────────────────────────────
#
#  O coletor NÃO roda a bancada: ingere o `--report` de quem já rodou. Logo os casos aqui são
#  sobre o CONTRATO DE INGESTÃO — e cada um existe porque um relatório mentiroso é indistinguível
#  de um verdadeiro para quem só lê a soma.
#
#  ⚠️ Sandbox obrigatório: o coletor deriva o destino do PRÓPRIO caminho (`ROOT/../..`), então a
#  cópia num tmpdir escreve o ledger LÁ. Sem isso, cada rodada da bancada sujaria
#  `docs/onion/metrics/selftest-runs.jsonl` com envelopes de teste — e a série existe justamente
#  para não ser contaminada por dado que não é medição.
run_selftest_series_selftests() {
  local sut="${REPO_ROOT}/ops/testing/collect-selftest.sh"
  if [ ! -f "${sut}" ]; then record_skip "selftest-series: coletor ausente (SUT não exercido)"; return; fi
  local sb rep out rc led
  _mk_series_sb() {   # monta um sandbox com o coletor em ops/testing/ e devolve em $sb
    sb="$(mktemp -d)"
    mkdir -p "${sb}/ops/testing" "${sb}/docs/onion/metrics"
    cp "${sut}" "${sb}/ops/testing/collect-selftest.sh"
    led="${sb}/docs/onion/metrics/selftest-runs.jsonl"
    # ⚠️ GIT REAL, COM COMMIT. Sem isto o `rev-parse HEAD` do coletor falha, o SHA vira o literal
    # `nao-declarado`, e TODA asserção de idempotência desta família rodava na chave DEGENERADA —
    # nunca na chave real (dia, source, sha) que a produção usa. Descoberto em 2026-09-11 ao curar
    # o achado de que chave-que-não-identifica não pode deduplicar: o caso (b) quebrou, e quebrou
    # por estar certo. É [[testar-no-caminho-errado-e-nao-testar]] dentro da própria bancada.
    ( cd "${sb}" && git init -q && git -c user.email=t@t -c user.name=t commit --allow-empty -qm seed ) 2>/dev/null
  }

  # (a) INGESTÃO + a partição fechando. O caminho feliz, mas ele assere a SOMA, não só o rc:
  #     um coletor que gravasse zeros sairia 0 e passaria num teste que só olha o exit code.
  _mk_series_sb
  rep="${sb}/r.tsv"
  printf 'familia\tpass\tfail\tskip\tsegundos\nalfa\t7\t0\t0\t3\nbeta\t5\t1\t0\t9\nTOTAL\t12\t1\t0\t12\n' > "${rep}"
  rc=0; out="$(bash "${sb}/ops/testing/collect-selftest.sh" --report "${rep}" --source local 2>&1)" || rc=$?
  if [ "${rc}" -eq 0 ] && [ -f "${led}" ] \
     && grep -q '"pass":12' "${led}" && grep -q '"familias":2' "${led}" \
     && grep -q '"familias_com_falha":\["beta"\]' "${led}"; then
    record_pass "selftest-series: (a) ingere o relatório e NOMEIA a família que falhou (não só a soma)"
  else record_fail "selftest-series: (a) ingestão" "rc=${rc} out=${out} ledger=$(cat "${led}" 2>/dev/null | head -c 200)"; fi
  rm -rf "${sb}"

  # (a2) SHARD: a mesma família em N linhas conta UMA família, e as somas se preservam. A
  #      família `fixtures` é fatiada em 8 shards e cada shard emite a sua linha — medido
  #      2026-09-09: 165 linhas para 158 famílias. A 1ª versão deste coletor gravava
  #      `"familias": len(fams)`, ou seja, contava LINHAS e chamava de famílias. Campo cujo
  #      NOME não é o que ele conta é a classe que esta onda persegue, cometida dentro dela;
  #      este caso é a fixture obrigatória dela.
  _mk_series_sb
  rep="${sb}/r.tsv"
  printf 'familia\tpass\tfail\tskip\tsegundos\nfixtures\t12\t0\t0\t30\nfixtures\t11\t0\t0\t20\nalfa\t7\t0\t0\t3\nTOTAL\t30\t0\t0\t53\n' > "${rep}"
  rc=0; out="$(bash "${sb}/ops/testing/collect-selftest.sh" --report "${rep}" --source local 2>&1)" || rc=$?
  if [ "${rc}" -eq 0 ] && grep -q '"familias":2,' "${led}" && grep -q '"linhas_relatorio":3' "${led}" \
     && grep -q '"pass":30' "${led}"; then
    record_pass "selftest-series: (a2) família fatiada em shards conta 1 família e 3 linhas — o campo diz o que conta"
  else record_fail "selftest-series: (a2) shard" "rc=${rc} out=${out} ledger=$(head -c 260 "${led}" 2>/dev/null)"; fi
  rm -rf "${sb}"

  # (a3) O ENVELOPE DECLARA SE A ÁRVORE ESTAVA SUJA. O `sha` sozinho mente por omissão: um
  #      envelope que diz `sha: abc1234` sobre uma árvore com mudanças não-commitadas afirma ter
  #      medido um commit que não foi o que rodou. Duas execuções do MESMO sha podem então
  #      divergir legitimamente, e quem lê a série conclui FLAKY onde houve edição — o detector
  #      passaria a inventar a categoria que ele existe para medir.
  _mk_series_sb
  rep="${sb}/r.tsv"
  printf 'familia\tpass\tfail\tskip\tsegundos\nalfa\t7\t0\t0\t3\nTOTAL\t7\t0\t0\t3\n' > "${rep}"
  bash "${sb}/ops/testing/collect-selftest.sh" --report "${rep}" --source local >/dev/null 2>&1
  if grep -qE '"dirty":(true|false)' "${led}"; then
    record_pass "selftest-series: (a3) o envelope declara \`dirty\` — o sha sozinho mentiria por omissão"
  else record_fail "selftest-series: (a3) dirty" "envelope sem o campo: $(head -c 240 "${led}" 2>/dev/null)"; fi
  rm -rf "${sb}"

  # (d2) A PARTIÇÃO FECHA NOS TRÊS PILARES, não só em `pass`. A 1ª versão checava só o `pass`,
  #      então `fail`/`skip` inconsistentes entravam e PERSISTIAM — e são justamente os dois que o
  #      detector de flaky lê para decidir. A guarda protegia o número que ninguém usa para decidir.
  _mk_series_sb
  rep="${sb}/r.tsv"
  printf 'familia\tpass\tfail\tskip\tsegundos\nalfa\t7\t1\t0\t3\nTOTAL\t7\t99\t0\t3\n' > "${rep}"
  rc=0; out="$(bash "${sb}/ops/testing/collect-selftest.sh" --report "${rep}" --source local 2>&1)" || rc=$?
  if [ "${rc}" -eq 2 ] && grep -q "'fail'" <<< "${out}" && [ ! -f "${led}" ]; then
    record_pass "selftest-series: (d2) TOTAL com \`fail\` que não bate → rc=2 NOMEANDO o pilar (não só \`pass\`)"
  else record_fail "selftest-series: (d2) partição nos 3 pilares" "rc=${rc} out=${out} — fail/skip inconsistentes entrariam no ledger que o detector de flaky lê"; fi
  rm -rf "${sb}"

  # (d3) SHA NÃO RESOLVIDO desativa a idempotência, e COLETA. A chave (dia, source, sha) com
  #      `sha=nao-declarado` COLIDE entre execuções genuinamente diferentes — a segunda seria
  #      descartada como duplicata e uma medição real sumiria em silêncio. Entre perder um run e
  #      guardar um duplicado, o duplicado é o erro barato: o ledger é append-only e o `ts`
  #      desambigua; o run perdido não volta.
  _mk_series_sb
  rm -rf "${sb}/.git"          # sem git ⇒ rev-parse falha ⇒ SHA vira 'nao-declarado'
  rep="${sb}/r.tsv"
  printf 'familia\tpass\tfail\tskip\tsegundos\nalfa\t7\t0\t0\t3\nTOTAL\t7\t0\t0\t3\n' > "${rep}"
  bash "${sb}/ops/testing/collect-selftest.sh" --report "${rep}" --source local >/dev/null 2>&1
  out="$(bash "${sb}/ops/testing/collect-selftest.sh" --report "${rep}" --source local 2>&1)" || true
  if [ "$(grep -c '^{' "${led}" 2>/dev/null || echo 0)" = "2" ] && grep -qi 'idempotência desativada' <<< "${out}"; then
    record_pass "selftest-series: (d3) sha não resolvido → idempotência DESLIGADA e o 2º run é COLETADO (perder medição é pior que duplicar)"
  else record_fail "selftest-series: (d3) chave que não identifica" "envelopes=$(grep -c '^{' "${led}" 2>/dev/null || echo 0) (esperava 2); out=${out}"; fi
  rm -rf "${sb}"

  # (d4) FLAKY conta EXECUÇÕES, não linhas de shard. Uma família fatiada emite N linhas na MESMA
  #      execução; contar linhas fazia `falhou 3/8` para um run só — FLAKY inventado onde não houve
  #      execução em que a família passou. O detector fabricava a categoria que existe para medir.
  _mk_series_sb
  rep="${sb}/r.tsv"
  printf 'familia\tpass\tfail\tskip\tsegundos\nshardada\t5\t1\t0\t3\nshardada\t5\t1\t0\t3\nshardada\t5\t0\t0\t3\nTOTAL\t15\t2\t0\t9\n' > "${rep}"
  bash "${sb}/ops/testing/collect-selftest.sh" --report "${rep}" --source local >/dev/null 2>&1
  out="$(bash "${sb}/ops/testing/collect-selftest.sh" --flaky 2>&1)" || true
  if grep -q 'falhou   1/1' <<< "${out}" && grep -q 'SEMPRE VERMELHA' <<< "${out}"; then
    record_pass "selftest-series: (d4) família fatiada em 3 shards numa execução conta 1/1 → SEMPRE VERMELHA, não FLAKY inventado"
  else record_fail "selftest-series: (d4) shard no detector" "out=${out} — se disser 2/3, o detector voltou a contar LINHAS e fabrica flaky"; fi
  rm -rf "${sb}"

  # (b) IDEMPOTÊNCIA — e este caso é a FIXTURE OBRIGATÓRIA do defeito que o motivou. Na 1ª
  #     versão o coletor gravou o MESMO envelope duas vezes: a guarda procurava a chave
  #     `"dia":"…"` sem espaços e o `json.dumps` default escrevia `"dia": "…"`. Guarda que checa
  #     um formato que o escritor não produz é guarda nenhuma — a classe desta onda inteira,
  #     cometida DENTRO dela. Pego pelo dogfood na 1ª invocação, não por releitura.
  _mk_series_sb
  rep="${sb}/r.tsv"
  printf 'familia\tpass\tfail\tskip\tsegundos\nalfa\t7\t0\t0\t3\nTOTAL\t7\t0\t0\t3\n' > "${rep}"
  bash "${sb}/ops/testing/collect-selftest.sh" --report "${rep}" --source local >/dev/null 2>&1
  bash "${sb}/ops/testing/collect-selftest.sh" --report "${rep}" --source local >/dev/null 2>&1
  if [ "$(grep -c '^{' "${led}" || true)" = "1" ]; then
    record_pass "selftest-series: (b) coletar 2× a mesma (dia,source,sha) grava UMA linha — a chave existe no formato que o escritor produz"
  else record_fail "selftest-series: (b) idempotência" "esperava 1 envelope, achei $(grep -c '^{' "${led}" || true) — a guarda checa um formato que o escritor não emite"; fi
  rm -rf "${sb}"

  # (c) RELATÓRIO SEM `TOTAL` → rc=2. É a assinatura da bancada que ABORTOU antes da soma
  #     (worker morto, SIGPIPE, OOM — os três já medidos aqui). Coletar isso registraria como
  #     execução o que não foi uma, e a série passaria a mentir para baixo em silêncio.
  _mk_series_sb
  rep="${sb}/r.tsv"
  printf 'familia\tpass\tfail\tskip\tsegundos\nalfa\t7\t0\t0\t3\n' > "${rep}"
  rc=0; out="$(bash "${sb}/ops/testing/collect-selftest.sh" --report "${rep}" --source local 2>&1)" || rc=$?
  if [ "${rc}" -eq 2 ] && grep -qi 'TOTAL' <<< "${out}" && [ ! -f "${led}" ]; then
    record_pass "selftest-series: (c) relatório sem TOTAL → rc=2 e NADA gravado (bancada abortada não é execução)"
  else record_fail "selftest-series: (c) sem TOTAL" "rc=${rc} out=${out}; ledger existe? $([ -f "${led}" ] && echo SIM || echo nao)"; fi
  rm -rf "${sb}"

  # (d) A PARTIÇÃO TEM DE FECHAR. Um TOTAL que não bate com as partes é um número que PARECE
  #     medido. Mesma asserção do ledger dos resíduos, pela mesma razão.
  _mk_series_sb
  rep="${sb}/r.tsv"
  printf 'familia\tpass\tfail\tskip\tsegundos\nalfa\t7\t0\t0\t3\nTOTAL\t999\t0\t0\t3\n' > "${rep}"
  rc=0; out="$(bash "${sb}/ops/testing/collect-selftest.sh" --report "${rep}" --source local 2>&1)" || rc=$?
  if [ "${rc}" -eq 2 ] && grep -q '999' <<< "${out}" && [ ! -f "${led}" ]; then
    record_pass "selftest-series: (d) soma das famílias ≠ TOTAL → rc=2 nomeando os dois números"
  else record_fail "selftest-series: (d) partição" "rc=${rc} out=${out}"; fi
  rm -rf "${sb}"

  # (e) `--source` em vocabulário FECHADO. A lição dos 262 resíduos aplicada ANTES de doer: a
  #     comparação CI × local é o que a série existe para permitir, e texto livre a destrói.
  _mk_series_sb
  rep="${sb}/r.tsv"
  printf 'familia\tpass\tfail\tskip\tsegundos\nalfa\t7\t0\t0\t3\nTOTAL\t7\t0\t0\t3\n' > "${rep}"
  rc=0; out="$(bash "${sb}/ops/testing/collect-selftest.sh" --report "${rep}" --source minha-maquina 2>&1)" || rc=$?
  if [ "${rc}" -eq 2 ] && grep -q 'local|ci|precommit|cron' <<< "${out}"; then
    record_pass "selftest-series: (e) --source fora do vocabulário → rc=2 listando os aceitos"
  else record_fail "selftest-series: (e) vocabulário de source" "rc=${rc} out=${out}"; fi
  rm -rf "${sb}"

  # (f) LEITURA sobre ledger AUSENTE é ⊘ NÃO MEDIDO, nunca "zero flaky". O terceiro desfecho
  #     desta onda, aplicado ao detector: ausência de observação não é evidência de saúde.
  _mk_series_sb
  rc=0; out="$(bash "${sb}/ops/testing/collect-selftest.sh" --flaky 2>&1)" || rc=$?
  if [ "${rc}" -eq 2 ] && grep -q 'NÃO MEDIDO' <<< "${out}"; then
    record_pass "selftest-series: (f) --flaky sem ledger → rc=2 ⊘ NÃO MEDIDO (não 'nenhum flaky')"
  else record_fail "selftest-series: (f) flaky sem ledger" "rc=${rc} out=${out}"; fi
  rm -rf "${sb}"

  # (g) (MUT) sem a asserção de partição, o TOTAL mentiroso de (d) é COLETADO. Guarda que nunca
  #     rejeitou é vacuidade — e esta guarda é a única coisa entre a série e um número inventado.
  _mk_series_sb
  # ⚠️ ÂNCORA RE-DERIVADA: a checagem virou LAÇO sobre os três pilares quando se curou que ela
  # fechava só o `pass`. O caso (g) acusou alto — `a mutação NÃO foi aplicada` — em vez de passar
  # decorativo, que é exatamente o que um mutation test tem de fazer quando o SUT muda de forma.
  sed -i "s/^    if _soma != total\[_pilar\]:/    if False:/" "${sb}/ops/testing/collect-selftest.sh"
  if grep -q 'if False:' "${sb}/ops/testing/collect-selftest.sh"; then
    rep="${sb}/r.tsv"
    printf 'familia\tpass\tfail\tskip\tsegundos\nalfa\t7\t0\t0\t3\nTOTAL\t999\t0\t0\t3\n' > "${rep}"
    rc=0; bash "${sb}/ops/testing/collect-selftest.sh" --report "${rep}" --source local >/dev/null 2>&1 || rc=$?
    if [ "${rc}" -eq 0 ] && grep -q '"pass":999' "${led}" 2>/dev/null; then
      record_pass "selftest-series: (g) (MUT) sem a asserção de partição o TOTAL mentiroso ENTRA na série — ela é load-bearing"
    else record_fail "selftest-series: (g) (MUT)" "mutante ainda recusou (rc=${rc}) — (d) passa por outro motivo"; fi
  else
    record_fail "selftest-series: (g) (MUT)" "a mutação NÃO foi aplicada — a âncora mudou e o teste não prova nada"
  fi
  rm -rf "${sb}"
}

# ── review_ledger — a camada de MÉTRICA tem UMA família na bancada, e é esta ──────────────────
#
#  Teto declarado no plano de 2026-09-08: a instrumentação de métrica recebe UMA família e ZERO
#  baselines. Se precisar de mais, o desenho está errado — instrumento mais caro que o
#  instrumentado é o risco nº3 desta onda, e o repo já tem 73 scripts e 155 famílias.
run_review_ledger_selftests() {
  local sut="${REPO_ROOT}/.claude/validation/review-ledger.sh"
  if [ ! -f "${sut}" ]; then record_skip "review-ledger: leitor ausente"; return; fi
  local d out rc
  d="$(mktemp -d)"
  # (a) DIRETÓRIO VAZIO É `NÃO MEDIDO`, jamais "nenhum achado". É a guarda de vacuidade da casa
  #     aplicada a um LEITOR: um ledger que soma zero sobre zero arquivos parece saúde.
  if out="$(bash "${sut}" --dir "${d}" 2>&1)"; then rc=0; else rc=$?; fi
  if [ "${rc}" -eq 2 ] && grep -q 'NÃO MEDIDO' <<< "${out}"; then
    record_pass "review-ledger: (a) diretório vazio ⇒ rc=2 NÃO MEDIDO (não 'zero achados')"
  else record_fail "review-ledger: (a) vacuidade" "rc=${rc}; $(tail -1 <<< "${out}" | cut -c1-90)"; fi
  # (b) diretório inexistente também reprova — ausência de alvo não vira zero silencioso
  if out="$(bash "${sut}" --dir "${d}/nao-existe" 2>&1)"; then rc=0; else rc=$?; fi
  if [ "${rc}" -eq 2 ]; then record_pass "review-ledger: (b) diretório ausente ⇒ rc=2"
  else record_fail "review-ledger: (b) dir ausente" "rc=${rc}"; fi
  # (c) A PARTIÇÃO FECHA: com-tokens + zerados + ausentes == total. Esta é a condição de aceite,
  #     e nasceu de um defeito DESTE script: a 1ª versão dizia "incompletos: 0" e usava 170 de
  #     262 — os 92 com `tokens: 0` sumiam num teste falsy, sem aparecer em lugar nenhum.
  out="$(bash "${sut}" --resumo 2>&1 || true)"
  local tot com zer aus
  tot="$(grep -oP 'LEDGER DA REVISÃO ADVERSARIAL — \K[0-9]+' <<< "${out}" || echo 0)"
  com="$(grep -oP 'tokens > 0 \(entram na média\)\s+\K[0-9]+' <<< "${out}" || echo 0)"
  zer="$(grep -oP '`tokens: 0` declarado\s+\K[0-9]+' <<< "${out}" || echo 0)"
  aus="$(grep -oP 'campo AUSENTE\s+\K[0-9]+' <<< "${out}" || echo 0)"
  if [ "${tot}" -gt 0 ] && [ "$(( com + zer + aus ))" -eq "${tot}" ]; then
    record_pass "review-ledger: (c) partição fecha — ${com}+${zer}+${aus} = ${tot} resíduos"
  else record_fail "review-ledger: (c) partição não fecha" "com=${com} zer=${zer} aus=${aus} tot=${tot}"; fi
  # (d) o TSV tem uma linha por resíduo (cabeçalho + N), e nenhuma célula vazia — vazio viraria
  #     coluna deslocada no consumidor, que é como um ledger passa a mentir sem ninguém ver.
  out="$(bash "${sut}" --tsv 2>/dev/null || true)"
  local n vazias
  n="$(printf '%s\n' "${out}" | tail -n +2 | grep -c . || true)"
  vazias="$(printf '%s\n' "${out}" | tail -n +2 | awk -F'\t' '{for(i=1;i<=NF;i++) if($i=="") c++} END{print c+0}')"
  if [ "${n}" -eq "${tot}" ] && [ "${vazias}" -eq 0 ]; then
    record_pass "review-ledger: (d) --tsv = ${n} linhas (1 por resíduo), zero célula vazia"
  else record_fail "review-ledger: (d) --tsv" "linhas=${n} esperado=${tot} células vazias=${vazias}"; fi
  rm -rf "${d}"
}
_family run_testing_state_selftests
_family run_ci_evidence_selftests
_family run_selftest_series_selftests
_family run_review_ledger_selftests


# Modo claude-md-fuse — D_ADOPT_ENTREGA_CLAUDE_MD_FUNDIDO (sinal upstream do 1º adotante greenfield, 2026-09-03): na adoção, um
# CLAUDE.md pré-existente que é BOILERPLATE de template (só comandos/estrutura/links) é FUNDIDO no esqueleto Onion-first,
# original preservado em seção nomeada; CLAUDE.md com regras reais segue never-clobber (helper recusa com exit 3).
run_claude_md_fuse_selftests() {
  local h="${REPO_ROOT}/.claude/utils/adopt/claude-md-fuse.sh"
  if [ ! -f "${h}" ]; then record_fail "claude-md-fuse" "helper ausente: ${h}"; return; fi
  local d out rc; d="$(mktemp -d)"
  printf '# Astro Starter Kit: Basics\n\n## 🚀 Project Structure\n\nInside of your Astro project, you will see the following folders and files:\n\n| Command | Action |\n| :--- | :--- |\n| `npm run dev` | Starts local dev server at `localhost:4321` |\n\n## 🧞 Commands\n\n- `npm run build`\n- [Astro docs](https://docs.astro.build)\n' > "${d}/astro.md"
  printf '# Projeto X\n\n## Regras\n- NUNCA commitar direto na main.\n' > "${d}/rules-marker.md"
  printf '# Projeto Y\n\nToda migration precisa de rollback testado antes do merge, e o time de dados revisa qualquer mudança de schema que afete relatórios regulatórios do trimestre.\n' > "${d}/rules-prose.md"
  printf '# 🧅 Alvo — regras do projeto\n\n## 🚪 Entrada\n- /onion · /warm-up\n' > "${d}/skel.md"
  out="$(bash "${h}" --classify "${d}/astro.md" 2>&1 || true)"
  if [ "${out}" = "boilerplate" ]; then record_pass "claude-md-fuse: (a) template Astro (tabela+comandos+links) ⇒ boilerplate"
  else record_fail "claude-md-fuse: (a)" "esperava boilerplate, veio: ${out}"; fi
  out="$(bash "${h}" --classify "${d}/rules-marker.md" 2>&1 || true)"
  if [ "${out}" = "rules" ]; then record_pass "claude-md-fuse: (b) marcador de regra (NUNCA) ⇒ rules"
  else record_fail "claude-md-fuse: (b)" "esperava rules, veio: ${out}"; fi
  out="$(bash "${h}" --classify "${d}/rules-prose.md" 2>&1 || true)"
  if [ "${out}" = "rules" ]; then record_pass "claude-md-fuse: (c) parágrafo de prosa ≥ 25 palavras ⇒ rules (recusa no incerto)"
  else record_fail "claude-md-fuse: (c)" "esperava rules, veio: ${out}"; fi
  # (f) LOCALE C, o do hook: marcador ACENTUADO em minúscula. `[ÓO]` casava um BYTE e `-i` não dobra caixa de
  #     multibyte em C — "é obrigatório" virava boilerplate e a fusão furava o never-clobber (passada 2026-09-13).
  printf '# Projeto Z\n\n- é obrigatório rodar os testes antes do merge.\n' > "${d}/rules-accent.md"
  out="$(LC_ALL=C LANG=C bash "${h}" --classify "${d}/rules-accent.md" 2>&1 || true)"
  if [ "${out}" = "rules" ]; then record_pass "claude-md-fuse: (f) 'é obrigatório' em LC_ALL=C ⇒ rules (marcador acentuado sobrevive ao locale do hook)"
  else record_fail "claude-md-fuse: (f) locale C" "esperava rules, veio: ${out}"; fi
  rc=0; bash "${h}" --fuse "${d}/astro.md" "${d}/skel.md" "${d}/fused.md" >/dev/null 2>&1 || rc=$?
  if [ "${rc}" -eq 0 ] && [ "$(head -1 "${d}/fused.md")" = "# 🧅 Alvo — regras do projeto" ] \
     && grep -q '^## 🛠️ Desenvolvimento — conteúdo original do template (Astro Starter Kit: Basics)' "${d}/fused.md" \
     && grep -qF '`npm run dev`' "${d}/fused.md" && ! grep -q '^# Astro Starter Kit' "${d}/fused.md"; then
    record_pass "claude-md-fuse: (d) fusão = esqueleto Onion primeiro + original preservado em seção nomeada (título vira nome da seção)"
  else record_fail "claude-md-fuse: (d) fusão" "rc=${rc}; $(head -3 "${d}/fused.md" 2>/dev/null | tr '\n' '|')"; fi
  rc=0; bash "${h}" --fuse "${d}/rules-marker.md" "${d}/skel.md" "${d}/fused2.md" >/dev/null 2>&1 || rc=$?
  if [ "${rc}" -eq 3 ] && [ ! -s "${d}/fused2.md" ]; then record_pass "claude-md-fuse: (e) CLAUDE.md com regras ⇒ recusa (exit 3), nada escrito — never-clobber preservado"
  else record_fail "claude-md-fuse: (e) recusa" "rc=${rc} (esperado 3); fused2 tem $(wc -c < "${d}/fused2.md" 2>/dev/null || echo 0) bytes"; fi
  rm -rf "${d}"
}
_family run_claude_md_fuse_selftests

# Modo instructions-loaded — L1 da poda de instruções (D_PODA_INSTRUCTION_BLOAT_CLAUDE_MD_E_SKILLS, opção C): o hook
# InstructionsLoaded registra CARGA (file/memory_type/load_reason) num jsonl fora do git; o censo projeta por arquivo ×
# motivo e marca candidatas (SO-SESSION-START / NUNCA). Nunca veta; nunca decide — a decisão de podar é por comportamento (L2).
run_instructions_loaded_selftests() {
  local hook="${REPO_ROOT}/.claude/hooks/instructions-loaded-log.sh" census="${REPO_ROOT}/.claude/validation/instructions-loaded-census.sh"
  if [ ! -f "${hook}" ] || [ ! -f "${census}" ]; then record_fail "instructions-loaded" "hook ou censo ausente"; return; fi
  if ! command -v python3 >/dev/null 2>&1; then record_skip "instructions-loaded: python3 ausente"; return; fi
  local d out rc; d="$(mktemp -d)"; mkdir -p "${d}/.claude/rules" "${d}/.claude/skills/x"
  printf -- '---\npaths: ["docs/**"]\n---\n# r\n' > "${d}/.claude/rules/r1.md"; printf -- '---\npaths: ["src/**"]\n---\n# s\n' > "${d}/.claude/skills/x/SKILL.md"
  # (a) hook: payload real (shape do binário 2.1.259) → 1 linha JSON com file relativo e load_reason; exit 0
  rc=0; printf '{"session_id":"abcdef123456","transcript_path":"/t","cwd":"%s","hook_event_name":"InstructionsLoaded","file_path":"%s/.claude/rules/r1.md","memory_type":"Project","load_reason":"path_glob_match","globs":["docs/**"],"trigger_file_path":"%s/docs/a.md"}' "${d}" "${d}" "${d}" \
    | ONION_INSTRUCTIONS_LOG="${d}/log.jsonl" CLAUDE_PROJECT_DIR="${d}" bash "${hook}" || rc=$?
  if [ "${rc}" -eq 0 ] && [ "$(wc -l < "${d}/log.jsonl")" -eq 1 ] && grep -q '"file": ".claude/rules/r1.md"' "${d}/log.jsonl" && grep -q '"load_reason": "path_glob_match"' "${d}/log.jsonl" && grep -q '"trigger": "docs/a.md"' "${d}/log.jsonl"; then
    record_pass "instructions-loaded: (a) hook apende 1 linha (file relativo, load_reason, trigger) e sai 0"
  else record_fail "instructions-loaded: (a) hook" "rc=${rc}; $(cat "${d}/log.jsonl" 2>/dev/null | head -c 200)"; fi
  # (b) hook com payload vazio/inválido → exit 0 e nada escrito (instrumento nunca derruba a sessão)
  rc=0; printf 'nao-e-json' | ONION_INSTRUCTIONS_LOG="${d}/log2.jsonl" CLAUDE_PROJECT_DIR="${d}" bash "${hook}" || rc=$?
  if [ "${rc}" -eq 0 ] && [ ! -s "${d}/log2.jsonl" ]; then record_pass "instructions-loaded: (b) payload inválido ⇒ exit 0, nada escrito"
  else record_fail "instructions-loaded: (b) inválido" "rc=${rc}; bytes=$(wc -c < "${d}/log2.jsonl" 2>/dev/null || echo 0)"; fi
  # (c) censo: r1 carregou por glob (candidata -), CLAUDE.md por session_start em 2 sessões, skill x com paths: nunca → NUNCA
  printf '%s\n' '{"ts":"t","session":"s1","file":"CLAUDE.md","memory_type":"Project","load_reason":"session_start","trigger":""}' '{"ts":"t","session":"s2","file":"CLAUDE.md","memory_type":"Project","load_reason":"session_start","trigger":""}' >> "${d}/log.jsonl"
  out="$(bash "${census}" --log "${d}/log.jsonl" --root "${d}" 2>&1 || true)"
  if grep -qE $'^CLAUDE.md\t2\t2\t0' <<< "${out}"&& grep -qE $'^.claude/rules/r1.md\t1\t0\t1' <<< "${out}"&& grep -qE $'^.claude/skills/x/SKILL.md\t0\t.*\tNUNCA$' <<< "${out}"; then
    record_pass "instructions-loaded: (c) censo por arquivo × motivo, sessões distintas contadas, paths: que nunca casou ⇒ NUNCA"
  else record_fail "instructions-loaded: (c) censo" "$(_emit "${out}" | head -4 | tr '\n' '|' | cut -c1-300)"; fi
  # (d) censo sem log ⇒ exit 3 nomeando a causa (não é zero silencioso)
  rc=0; out="$(bash "${census}" --log "${d}/nao-existe.jsonl" --root "${d}" 2>&1)" || rc=$?
  if [ "${rc}" -eq 3 ] && grep -q "sem censo" <<< "${out}"; then record_pass "instructions-loaded: (d) sem log ⇒ exit 3 declarando (nunca 0 calado)"
  else record_fail "instructions-loaded: (d) sem log" "rc=${rc}; ${out:0:120}"; fi
  rm -rf "${d}"
}
_family run_instructions_loaded_selftests

# Modo core-only-role — Q_SELFTEST_VENDORIZADO_INSATISFAZIVEL_NO_ADOTANTE, cura (a): com o stamp `role: adopted`, as famílias
# e fixtures core-only pulam com ⊘ VISÍVEL; sem stamp (core) rodam. Medido família-a-família na cópia de um adotante
# greenfield (2026-09-03): 118 passam, 12 são core-only por SSOT/maquinaria, 3 abortos de robustez curados.
run_core_only_role_selftests() {
  local sut="${REPO_ROOT}/.claude/validation/lint-selftest.sh" d out
  d="$(mktemp -d)"; cp -a "${REPO_ROOT}/.claude" "${d}/.claude"; cp -a "${REPO_ROOT}/docs" "${d}/docs"; cp -a "${REPO_ROOT}/CLAUDE.md" "${d}/CLAUDE.md"
  rm -rf "${d}/.claude/sessions" "${d}/.claude/worktrees"
  printf 'framework: onion-evolve\nsource_commit: 0000000\nrole: adopted\n' > "${d}/.claude/.onion-version"
  # (a) adotante: família core-only ⇒ ⊘ e sem ✗/✓ dela; família comum roda normalmente
  out="$(bash "${d}/.claude/validation/lint-selftest.sh" --families rules_registry,ladder_integrity 2>&1 || true)"
  if grep -q '⊘ rules_registry: core-only (role: adopted' <<< "${out}"&& ! grep -q 'rules-registry: (' <<< "${out}" \
     && grep -q '✓ ladder-integrity' <<< "${out}"; then
    record_pass "core-only-role: (a) role adopted ⇒ família core-only pula com ⊘ nomeando o motivo; família comum roda"
  else record_fail "core-only-role: (a)" "$(_emit "${out}" | grep -E '⊘|✗|Passaram' | head -3 | tr '\n' '|' | cut -c1-240)"; fi
  # (b) adotante: fixtures r16/r22 ⇒ ⊘ (nunca ✗) — só as 4 primeiras linhas r16 do manifest, para não pagar 94 lints
  { grep -E '^kind' "${REPO_ROOT}/.claude/validation/fixtures/manifest.tsv"; grep -E '^lint\s+r16-count-drift/' "${REPO_ROOT}/.claude/validation/fixtures/manifest.tsv" | sed -n '1,2p'; grep -E '^lint\s+r12-' "${REPO_ROOT}/.claude/validation/fixtures/manifest.tsv" | sed -n '1p'; } > "${d}/.claude/validation/fixtures/manifest.tsv"
  out="$(bash "${d}/.claude/validation/lint-selftest.sh" --families fixtures 2>&1 || true)"
  if [ "$(_emit "${out}" | grep -c '⊘ fixtures: r16-count-drift/')" -eq 2 ] && ! grep -q '✗ r16' <<< "${out}"&& grep -qE '✓ r12-' <<< "${out}"; then
    record_pass "core-only-role: (b) role adopted ⇒ fixtures r16 ⊘ (2/2), fixture comum ✓"
  else record_fail "core-only-role: (b) fixtures" "$(_emit "${out}" | grep -E '⊘|✗|✓' | head -4 | tr '\n' '|' | cut -c1-240)"; fi
  # (c) core (sem stamp): a mesma família core-only RODA
  rm -f "${d}/.claude/.onion-version"
  out="$(bash "${d}/.claude/validation/lint-selftest.sh" --families rules_registry 2>&1 || true)"
  if grep -q '✓ rules-registry: (' <<< "${out}"&& ! grep -q 'core-only' <<< "${out}"; then
    record_pass "core-only-role: (c) sem stamp (core) ⇒ a família core-only roda"
  else record_fail "core-only-role: (c) core" "$(_emit "${out}" | grep -E '⊘|✗|✓' | head -3 | tr '\n' '|' | cut -c1-200)"; fi
  rm -rf "${d}"
}
_family run_core_only_role_selftests

# Modo model-ladder — a ESCADA de modelos (D_COMANDOS_SEM_MODEL_OU_NO_LINEUP, selo 2026-09-03: piso Sonnet + opção A):
# guarda com piso só-por-fallback e campo ladder; aviso de degradação por prompt; REGRA 70 (fallbackModel projetado);
# REGRA 71 (comando sem model:); sonda de acesso por degrau com `claude` falso.
run_model_ladder_selftests() {
  local hk="${REPO_ROOT}/.claude/hooks/premodelswitch-guard.sh" nt="${REPO_ROOT}/.claude/hooks/session-degraded-notice.sh"
  local lint="${REPO_ROOT}/.claude/validation/lint-artifacts.sh" probe="${REPO_ROOT}/ops/model-lineup-probe.sh"
  for f in "${hk}" "${nt}" "${lint}" "${probe}"; do [ -f "${f}" ] || { record_fail "model-ladder" "ausente: ${f}"; return; }; done
  local d out rc; d="$(mktemp -d)"
  printf 'axes:\n  - id: E6-fronteira-modelos\n    session_models:\n      - claude-fable-5-1\n      - claude-opus-5\n    session_floor: claude-sonnet-5\n' > "${d}/bl.yaml"
  _sw() { # from to requested source → rc ; log em ${d}/log.jsonl
    printf '{"session_id":"sess-1","hook_event_name":"PreModelSwitch","from_model":"%s","to_model":"%s","requested_model":"%s","source":"%s","context_tokens":10,"estimated_cache_write_usd":0.1}' "$1" "$2" "$3" "$4" \
      | ONION_RADAR_BASELINES="${d}/bl.yaml" ONION_MODEL_SWITCH_LOG="${d}/log.jsonl" CLAUDE_PROJECT_DIR="${d}" CLAUDE_CODE_SESSION_ID=sess-1 bash "${hk}" >/dev/null 2>"${d}/err"; echo $?; }
  # (a) piso pelo picker ⇒ VETO (exit 2) nomeando o piso
  rc="$(_sw claude-fable-5-1 claude-sonnet-5 sonnet picker)"
  if [ "${rc}" = 2 ] && grep -q "PISO da escada" "${d}/err"; then record_pass "model-ladder: (a) piso pelo /model ⇒ VETO nomeando o piso"
  else record_fail "model-ladder: (a) piso/picker" "rc=${rc}: $(head -c 120 "${d}/err")"; fi
  # (b) piso por fallback ⇒ permite, ladder=degraded, aviso no stderr
  rc="$(_sw claude-fable-5-1 claude-sonnet-5 sonnet fallback)"
  if [ "${rc}" = 0 ] && tail -1 "${d}/log.jsonl" | grep -q '"decision":"allow","ladder":"degraded"' && grep -q "DEGRADADA" "${d}/err"; then
    record_pass "model-ladder: (b) piso por fallback ⇒ permite com ladder=degraded e aviso"
  else record_fail "model-ladder: (b) piso/fallback" "rc=${rc}; $(tail -1 "${d}/log.jsonl" | cut -c1-160)"; fi
  # (c) aviso de degradação a cada prompt enquanto degradado; silêncio após restored
  out="$(printf '{"session_id":"sess-1","hook_event_name":"UserPromptSubmit","prompt":"x"}' | ONION_MODEL_SWITCH_LOG="${d}/log.jsonl" CLAUDE_PROJECT_DIR="${d}" CLAUDE_CODE_SESSION_ID=sess-1 bash "${nt}" 2>&1 || true)"
  rc="$(_sw claude-sonnet-5 claude-fable-5-1 fable picker)"
  local out2; out2="$(printf '{"session_id":"sess-1","hook_event_name":"UserPromptSubmit","prompt":"x"}' | ONION_MODEL_SWITCH_LOG="${d}/log.jsonl" CLAUDE_PROJECT_DIR="${d}" CLAUDE_CODE_SESSION_ID=sess-1 bash "${nt}" 2>&1 || true)"
  if grep -q "DEGRADADA na escada" <<< "${out}"&& grep -q "claude-sonnet-5" <<< "${out}"&& [ -z "${out2}" ] && [ "${rc}" = 0 ] && tail -1 "${d}/log.jsonl" | grep -q '"ladder":"restored"'; then
    record_pass "model-ladder: (c) aviso a cada prompt enquanto degradado; volta ao primário ⇒ ladder=restored e silêncio"
  else record_fail "model-ladder: (c) aviso" "out='${out:0:80}' out2='${out2:0:40}' rc=${rc}"; fi
  # (d) fora da escada pelo picker ⇒ VETO (o 1+3 continua)
  rc="$(_sw claude-fable-5-1 claude-haiku-4-5 haiku picker)"
  if [ "${rc}" = 2 ]; then record_pass "model-ladder: (d) fora da escada ⇒ VETO (1+3 intacto)"; else record_fail "model-ladder: (d) fora" "rc=${rc}"; fi
  # (e) REGRA 70: settings.fallbackModel diverge da escada ⇒ HARD; projetado ⇒ silêncio
  printf '{"fallbackModel":["claude-opus-5"]}\n' > "${d}/s-bad.json"; printf '{"fallbackModel":["claude-opus-5","claude-sonnet-5"]}\n' > "${d}/s-ok.json"
  out="$(ONION_RADAR_BASELINES="${d}/bl.yaml" ONION_SETTINGS_JSON="${d}/s-bad.json" bash "${lint}" --only="${d}/s-bad.json" 2>&1 || true)"
  local out_ok; out_ok="$(ONION_RADAR_BASELINES="${d}/bl.yaml" ONION_SETTINGS_JSON="${d}/s-ok.json" bash "${lint}" --only="${d}/s-ok.json" 2>&1 || true)"
  if grep -q "REGRA 70 (" <<< "${out}"&& grep -q "diverge da escada" <<< "${out}"&& ! grep -q "REGRA 70 (" <<< "${out_ok}"; then
    record_pass "model-ladder: (e) REGRA 70: fallbackModel divergente ⇒ HARD; projetado da escada ⇒ silêncio"
  else record_fail "model-ladder: (e) REGRA 70" "bad: $(_emit "${out}" | grep -c 'REGRA 70') ok: $(_emit "${out_ok}" | grep -c 'REGRA 70')"; fi
  # (f) REGRA 71: comando com model: ⇒ HARD (fixture dentro de .claude/commands numa cópia)
  mkdir -p "${d}/repo/.claude/commands/quick"; cp -a "${REPO_ROOT}/.claude/validation" "${d}/repo/.claude/validation"
  printf -- '---\nname: probe-model\ndescription: x\nmodel: sonnet\ncategory: quick\ntags: [a, b, c]\nversion: "1.0.0"\nupdated: "2026-09-03"\n---\n# x\n' > "${d}/repo/.claude/commands/quick/probe-model.md"
  out="$(cd "${d}/repo" && bash .claude/validation/lint-artifacts.sh --only="${d}/repo/.claude/commands/quick/probe-model.md" 2>&1 || true)"
  if grep -q "REGRA 71 (" <<< "${out}"&& grep -q "comando declara model:" <<< "${out}"; then record_pass "model-ladder: (f) REGRA 71: comando com model: ⇒ HARD"
  else record_fail "model-ladder: (f) REGRA 71" "$(_emit "${out}" | grep -E 'REGRA 71|HARD' | head -2 | tr '\n' '|' | cut -c1-200)"; fi
  # (g) sonda: claude falso — primário ok, fallback ok, piso negado ⇒ TSV com 3 linhas e exit 1
  mkdir -p "${d}/bin"; printf '#!/usr/bin/env bash\ncase "$*" in *claude-sonnet-5*) echo "Error: model not available on this plan" >&2; exit 1;; esac; echo ok\n' > "${d}/bin/claude"; chmod +x "${d}/bin/claude"
  out="$(ONION_CC_BIN="${d}/bin/claude" bash "${probe}" --baseline "${d}/bl.yaml" --jsonl "${d}/probe.jsonl" --timeout 5 2>&1)" && rc=0 || rc=$?
  if [ "${rc}" -eq 1 ] && grep -qE $'^claude-fable-5-1\tok' <<< "${out}"&& grep -qE $'^claude-sonnet-5\tdenied' <<< "${out}"&& [ "$(wc -l < "${d}/probe.jsonl")" -eq 3 ]; then
    record_pass "model-ladder: (g) sonda: ok/ok/denied por degrau, jsonl datado, exit 1 quando algum degrau nega"
  else record_fail "model-ladder: (g) sonda" "rc=${rc}; $(_emit "${out}" | head -4 | tr '\n' '|' | cut -c1-200)"; fi
  rm -rf "${d}"
}
_family run_model_ladder_selftests
# Modo plugin-version-derived — a versão do plugin ANDA com o conteúdo (sinal de campo 2026-09-03: `claude plugin update`
# compara só a versão; manifesto parado em 0.1.0 = updater no-op com o cache 89 arquivos atrás). Sandbox git próprio.
run_plugin_version_derived_selftests() {
  local asm="${REPO_ROOT}/.claude/utils/marketplace/assemble-plugin.sh"
  [ -f "${asm}" ] || { record_fail "plugin-version-derived" "assembler ausente"; return; }
  local d v1 v2 v3 v4; d="$(mktemp -d)"
  mkdir -p "${d}/src/.claude/commands/quick" "${d}/src/.claude/utils/marketplace/verticals"
  printf -- '---\nname: ping\ndescription: x\ncategory: quick\ntags: [a, b, c]\nversion: "1.0.0"\nupdated: "2026-09-03"\n---\n# ping\n' > "${d}/src/.claude/commands/quick/ping.md"
  printf 'PLUGIN_NAME="probe"\nPLUGIN_VERSION="0.1.0"\nPLUGIN_DESC="probe"\nKEYWORDS=(probe)\nCOMMANDS=(.claude/commands/quick/ping.md)\nAGENTS=()\nUTILS=()\nVALIDATION=()\nTEMPLATES=()\nSKILLS=()\nHOOKS=()\nDOCS=()\n' > "${d}/src/.claude/utils/marketplace/verticals/probe.manifest.sh"
  ( cd "${d}/src" && git init -q && git add -A && git -c user.email=t@t -c user.name=t commit -qm seed ) >/dev/null 2>&1
  # GERA NO CANONICO (`<src>/plugins/<name>`), que e de onde o fato commitado e lido. Gerar num
  # `out/` lateral faria todo caso partir de "sem anterior" e o contrato nao seria exercitado.
  _ver() { bash "${asm}" "${d}/src/.claude/utils/marketplace/verticals/probe.manifest.sh" "${d}/src" >/dev/null 2>&1; sed -n 's/.*"version"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' "${d}/src/plugins/probe/.claude-plugin/plugin.json" | head -1; }
  # ⚠️ OS CASOS (a)(b)(c) FORAM REESCRITOS, nao remendados. Eles codificavam a semantica ANTIGA
  #    (`0.1.<n de commits que tocaram as fontes>`), que caiu na passada adversarial de 2026-09-11.
  #    Ajustar so os numeros esperados manteria a forma de um contrato que nao existe mais — e
  #    teste que afirma um contrato morto e pior que teste ausente: ele da confianca no errado.

  # (a) A VERSAO SAI DO FATO COMMITADO, nao do historico. Sem plugin gerado ainda, fica a do
  #     manifesto; gerado e commitado, a proxima geracao parte DAQUELE numero.
  v1="$(_ver)"
  ( cd "${d}/src" && git add -A && git -c user.email=t@t -c user.name=t commit -qm gen ) >/dev/null 2>&1
  v2="$(_ver)"
  if [ "${v1}" = "0.1.0" ] && [ "${v2}" = "0.1.0" ]; then
    record_pass "plugin-version-derived: (a) 1a geracao usa a versao do manifesto (${v1}) e nao anda sozinha depois de commitada"
  else record_fail "plugin-version-derived: (a)" "v1=${v1} v2=${v2} (esperado 0.1.0 nas duas — a versao nao pode nascer de historico)"; fi

  # (b) CONTEUDO MUDOU ⇒ +1, e o numero e o MESMO antes e depois do commit. E o invariante que faz
  #     o pre-commit e o CI concordarem: os dois derivam da ARVORE, nao do estado do indice.
  printf '# ping v2\n' >> "${d}/src/.claude/commands/quick/ping.md"
  v3="$(_ver)"
  ( cd "${d}/src" && git add -A && git -c user.email=t@t -c user.name=t commit -qm change ) >/dev/null 2>&1
  v4="$(_ver)"
  if [ "${v3}" = "0.1.1" ] && [ "${v4}" = "0.1.1" ]; then
    record_pass "plugin-version-derived: (b) conteudo mudou ⇒ 0.1.1, identico antes E depois do commit (pre-commit = CI)"
  else record_fail "plugin-version-derived: (b)" "antes=${v3} depois=${v4} (esperado 0.1.1/0.1.1)"; fi

  # (c) COMMIT QUE NAO TOCA AS FONTES nao anda a versao — o `tree_sha` nao muda, logo nao ha +1.
  #     Intencao preservada do caso original; so a aritmetica mudou de referencial.
  printf '# outro\n' > "${d}/src/README.md"
  ( cd "${d}/src" && git add -A && git -c user.email=t@t -c user.name=t commit -qm unrelated ) >/dev/null 2>&1
  v1="$(_ver)"
  if [ "${v1}" = "0.1.1" ]; then
    record_pass "plugin-version-derived: (c) commit que NAO toca as fontes nao anda a versao (${v1})"
  else record_fail "plugin-version-derived: (c)" "esperava 0.1.1 apos commit alheio, veio ${v1}"; fi

  v1="$(ONION_PLUGIN_VERSION_DERIVED=0 bash "${asm}" "${d}/src/.claude/utils/marketplace/verticals/probe.manifest.sh" "${d}/src" "${d}/out2" >/dev/null 2>&1; grep -oE '"version": *"[^"]+"' "${d}/out2/.claude-plugin/plugin.json" | grep -oE '[0-9.]+')"
  if [ "${v1}" = "0.1.0" ]; then record_pass "plugin-version-derived: (d) ONION_PLUGIN_VERSION_DERIVED=0 ⇒ versão do manifesto (legado)"
  else record_fail "plugin-version-derived: (d)" "esperava 0.1.0, veio ${v1}"; fi

  # ── A VERSAO E UM FATO COMMITADO — um caso por REQUISITO ────────────────────────────────────
  # Os casos (e)..(i) nasceram de uma passada adversarial que reprovou as DUAS tentativas
  # anteriores. A licao: enquanto a versao for funcao do HISTORICO ou do REMOTO, ela nao pode ser
  # ao mesmo tempo reproduzivel-da-arvore (o que a REGRA 19 exige) e estavel (o que um PR aberto
  # exige). Cada caso abaixo prende UM dos quatro requisitos, e cada um morreu com mutante proprio.
  local e out1 out2
  _setup_repo() {   # $1 = dir; repo com um plugin ja GERADO e commitado
    e="$1"; mkdir -p "${e}/.claude/commands/quick" "${e}/.claude/utils/marketplace/verticals"
    cp -r "${REPO_ROOT}/.claude/utils/marketplace" "${e}/.claude/utils/" 2>/dev/null || true
    printf -- '---\nname: ping\ndescription: x\ncategory: quick\ntags: [a, b, c]\nversion: "1.0.0"\nupdated: "2026-09-03"\n---\n# ping\n' > "${e}/.claude/commands/quick/ping.md"
    printf 'PLUGIN_NAME="probe"\nPLUGIN_VERSION="0.1.0"\nPLUGIN_DESC="probe"\nKEYWORDS=(probe)\nCOMMANDS=(.claude/commands/quick/ping.md)\nAGENTS=()\nUTILS=()\nVALIDATION=()\nTEMPLATES=()\nSKILLS=()\nHOOKS=()\nDOCS=()\n' > "${e}/.claude/utils/marketplace/verticals/probe.manifest.sh"
    ( cd "${e}" && git init -q -b main && git add -A && git -c user.email=t@t -c user.name=t commit -qm seed ) >/dev/null 2>&1
  }
  _regen() { bash "${asm}" "$1/.claude/utils/marketplace/verticals/probe.manifest.sh" "$1" "${2:-$1/plugins/probe}" >/dev/null 2>&1; }
  _vof()   { sed -n 's/.*"version"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' "$1/.claude-plugin/plugin.json" | head -1; }
  _bump()  { printf '# %s\n' "$2" >> "$1/.claude/commands/quick/ping.md"
             _regen "$1"
             ( cd "$1" && git add -A && git -c user.email=t@t -c user.name=t commit -qm "$2" ) >/dev/null 2>&1; }

  # (e) REQUISITO 1 — MESMA ARVORE, MESMO NUMERO. E o que a REGRA 19 compara: ela regenera num
  #     mktemp e confronta com o canonico. Se os dois nao derivarem igual, o gate reprova SEMPRE.
  #     ⚠️ Este caso pegou um defeito REAL antes de qualquer commit: a 1a versao lia o fato
  #     commitado DEPOIS do `rm -rf "${DEST}"`, entao regenerar no canonico zerava a versao para
  #     0.1.0 — um plugin com 255 publicadas voltaria a zero.
  e="$(mktemp -d)"; _setup_repo "$e"; _regen "$e"
  ( cd "$e" && git add -A && git -c user.email=t@t -c user.name=t commit -qm gen ) >/dev/null 2>&1
  # ⚠️ A VERSAO COMMITADA TEM DE DIVERGIR DA DO MANIFESTO, senao o caso nao discrimina: um motor
  #    que lesse o anterior do lugar ERRADO cairia no default do manifesto e daria o MESMO numero
  #    por acidente. Medido — o mutante "le o anterior do DEST" (o bug do `rm -rf`, que aconteceu
  #    de verdade) sobrevivia a este caso enquanto as duas versoes eram 0.1.0.
  _bump "$e" antes-da-comparacao
  local _canon_v _temp_v _t; _t="$(mktemp -d)"
  _regen "$e"; _canon_v="$(_vof "$e/plugins/probe")"
  _regen "$e" "$_t/probe"; _temp_v="$(_vof "$_t/probe")"
  if [ -n "${_canon_v}" ] && [ "${_canon_v}" = "${_temp_v}" ]; then
    if [ "${_canon_v}" = "0.1.0" ]; then
      record_fail "plugin-version-derived: (e)" "os dois deram 0.1.0 (o default do manifesto) — o caso nao discrimina; a fixture precisa de versao commitada != manifesto"
    else
      record_pass "plugin-version-derived: (e) canonico e temp derivam o MESMO numero (${_canon_v}, != manifesto) — e o que a REGRA 19 compara"
    fi
  else record_fail "plugin-version-derived: (e)" "canonico=${_canon_v} temp=${_temp_v} — a REGRA 19 reprovaria sempre"; fi
  rm -rf "$_t" "$e"

  # (f) REQUISITO 2 — IMUNE AO SQUASH-MERGE, que e como esta casa funde. A tentativa 1 quebrava
  #     aqui: N commits da branch viravam UM no main, a branch publicava N a mais.
  e="$(mktemp -d)"; _setup_repo "$e"; _regen "$e"
  ( cd "$e" && git add -A && git -c user.email=t@t -c user.name=t commit -qm gen ) >/dev/null 2>&1
  local _base_v _branch_v _main_v _re_v
  _base_v="$(_vof "$e/plugins/probe")"
  ( cd "$e" && git checkout -qb feat ) >/dev/null 2>&1
  _bump "$e" c1; _bump "$e" c2
  _branch_v="$(_vof "$e/plugins/probe")"
  ( cd "$e" && git checkout -q main && git merge --squash -q feat >/dev/null 2>&1 && git -c user.email=t@t -c user.name=t commit -qm squash ) >/dev/null 2>&1
  _main_v="$(_vof "$e/plugins/probe")"
  _regen "$e"; _re_v="$(_vof "$e/plugins/probe")"
  if [ "${_branch_v}" = "${_main_v}" ] && [ "${_main_v}" = "${_re_v}" ] && [ "${_branch_v}" != "${_base_v}" ]; then
    record_pass "plugin-version-derived: (f) squash real: branch previu ${_branch_v}, main ficou ${_main_v}, regeneracao no main deu ${_re_v} — os tres batem"
  else record_fail "plugin-version-derived: (f)" "base=${_base_v} branch=${_branch_v} main-pos-squash=${_main_v} regenerado=${_re_v} — o squash dessincronizou"; fi
  rm -rf "$e"

  # (g) REQUISITO 3 — ESTAVEL AO QUE OUTRO PR FAZ. A tentativa 2 quebrava aqui: a versao virava
  #     funcao do REMOTO e um PR aberto passava a reprovar a REGRA 19 sozinho quando OUTRO mergeava.
  e="$(mktemp -d)"; _setup_repo "$e"; _regen "$e"
  ( cd "$e" && git add -A && git -c user.email=t@t -c user.name=t commit -qm gen && git checkout -qb meupr ) >/dev/null 2>&1
  _bump "$e" meu
  local _before _after; _before="$(_vof "$e/plugins/probe")"
  ( cd "$e" && git stash -q -u 2>/dev/null; git checkout -q main && git checkout -qb outro ) >/dev/null 2>&1
  _bump "$e" outro
  ( cd "$e" && git checkout -q main && git merge --squash -q outro >/dev/null 2>&1 && git -c user.email=t@t -c user.name=t commit -qm sq2 && git checkout -q meupr ) >/dev/null 2>&1
  _regen "$e"; _after="$(_vof "$e/plugins/probe")"
  if [ "${_before}" = "${_after}" ]; then
    record_pass "plugin-version-derived: (g) o PR aberto ficou em ${_before} enquanto OUTRO mergeava — versao nao e funcao do remoto"
  else record_fail "plugin-version-derived: (g)" "o PR aberto mudou de ${_before} para ${_after} sozinho — a REGRA 19 reprovaria um PR que ninguem tocou"; fi
  rm -rf "$e"

  # (h) REQUISITO 4 — NAO CONGELA SOB GITFLOW. A tentativa 2 congelava: `main` parado, `develop`
  #     andando, cinco commits e o MESMO numero — literalmente o dano que ela invocava como razao.
  e="$(mktemp -d)"; _setup_repo "$e"; _regen "$e"
  ( cd "$e" && git add -A && git -c user.email=t@t -c user.name=t commit -qm gen && git checkout -qb develop ) >/dev/null 2>&1
  local _seq="" _k
  for _k in d1 d2 d3; do _bump "$e" "${_k}"; _seq="${_seq} $(_vof "$e/plugins/probe")"; done
  if [ "$(printf '%s\n' ${_seq} | sort -u | grep -c . || true)" = "3" ]; then
    record_pass "plugin-version-derived: (h) em GitFlow (main parado, develop andando) a versao ANDA:${_seq}"
  else record_fail "plugin-version-derived: (h)" "a versao congelou em develop:${_seq}"; fi
  rm -rf "$e"

  # (j) O TETO DA VERSAO E BARRADO DUAS VEZES — e este caso existe porque eu afirmei o contrario.
  #     Dois PRs concorrentes, da mesma base, calculam o MESMO numero. A afirmacao de 2026-09-12 foi
  #     que no esquema de fato commitado a colisao passaria CALADA. Medido com squash real em
  #     2026-09-13, e falso, e o selo do maestro fechou a decisao SEM codigo por isso. O que sobra e
  #     garantir que as duas barreiras nao sumam em silencio numa mudanca de formato da projecao:
  #       (j1) o GIT conflita no merge do 2o PR — as projecoes divergem;
  #       (j2) resolvido DESCUIDADO (aceitando um lado), a REGRA 19 acusa drift, porque o tree_sha
  #            commitado e de UM lado e a arvore real e A+B.
  e="$(mktemp -d)"; _setup_repo "$e"; _regen "$e"
  ( cd "$e" && git add -A && git -c user.email=t@t -c user.name=t commit -qm gen ) >/dev/null 2>&1
  ( cd "$e" && git checkout -qb prA ) >/dev/null 2>&1; _bump "$e" A
  ( cd "$e" && git checkout -q main && git checkout -qb prB ) >/dev/null 2>&1
  printf '# B\n' > "$e/.claude/commands/quick/extra-b.md"
  sed -i 's|COMMANDS=(.claude/commands/quick/ping.md)|COMMANDS=(.claude/commands/quick/ping.md .claude/commands/quick/extra-b.md)|' "$e/.claude/utils/marketplace/verticals/probe.manifest.sh"
  _regen "$e"; ( cd "$e" && git add -A && git -c user.email=t@t -c user.name=t commit -qm B ) >/dev/null 2>&1
  local _merge_rc=0 _vA _j2_c _j2_d _t
  ( cd "$e" && git checkout -q main && git merge --squash -q prA >/dev/null 2>&1 && git -c user.email=t@t -c user.name=t commit -qm sqA ) >/dev/null 2>&1
  _vA="$(_vof "$e/plugins/probe")"
  ( cd "$e" && git merge --squash prB ) >/dev/null 2>&1 || _merge_rc=$?
  if [ "${_merge_rc}" -ne 0 ]; then
    record_pass "plugin-version-derived: (j1) 2o PR concorrente sem rebase CONFLITA no git — a colisao nao entra calada"
  else record_fail "plugin-version-derived: (j1)" "o merge do 2o PR NAO conflitou — a 1a barreira do teto sumiu (formato da projecao mudou?)"; fi
  # resolucao DESCUIDADA: aceita o plugins/ de UM lado (o do prB), por checkout EXPLICITO da branch e
  # nao por `--theirs`. Medido 2026-09-13: o caso passava no git 2.43 local e MATAVA o worker no git 2.55
  # do CI (a familia "reivindicada e NAO concluida") — a resolucao por estagio de conflito depende da
  # versao do git, e um passo que falha sob `set -e` nao reprova, some. Agora nenhum passo pode sumir:
  # cada um tolera a falha e o caso REPROVA dizendo em qual parou.
  local _j2_step="ok"
  ( cd "$e" && git checkout prB -- plugins/ && git add -A && git -c user.email=t@t -c user.name=t commit -qm sqB-descuidado ) >/dev/null 2>&1 || _j2_step="resolucao-nao-commitou"
  _t="$(mktemp -d)"
  _j2_c="$(_vof "$e/plugins/probe" 2>/dev/null || true)"
  _regen "$e" "$_t/probe" || _j2_step="${_j2_step}+regen-falhou"
  _j2_d="$(_vof "$_t/probe" 2>/dev/null || true)"
  if [ "${_j2_step}" = "ok" ] && [ -n "${_j2_c}" ] && [ -n "${_j2_d}" ] && [ "${_j2_c}" != "${_j2_d}" ]; then
    record_pass "plugin-version-derived: (j2) resolucao descuidada e pega pela REGRA 19 — commitado ${_j2_c}, derivado ${_j2_d}"
  else record_fail "plugin-version-derived: (j2)" "passo=${_j2_step} · commitado=[${_j2_c}] derivado=[${_j2_d}] — se os dois batem, a 2a barreira do teto sumiu e a colisao passaria calada"; fi
  rm -rf "$_t" "$e"

  # (i) IDEMPOTENCIA — regenerar sem mudar conteudo NAO pode andar. Sem isto a versao dispararia a
  #     cada invocacao do lint e a REGRA 19 nunca fecharia.
  e="$(mktemp -d)"; _setup_repo "$e"; _regen "$e"
  ( cd "$e" && git add -A && git -c user.email=t@t -c user.name=t commit -qm gen ) >/dev/null 2>&1
  local _i1 _i2 _i3
  _regen "$e"; _i1="$(_vof "$e/plugins/probe")"
  _regen "$e"; _i2="$(_vof "$e/plugins/probe")"
  _regen "$e"; _i3="$(_vof "$e/plugins/probe")"
  if [ "${_i1}" = "${_i2}" ] && [ "${_i2}" = "${_i3}" ]; then
    record_pass "plugin-version-derived: (i) tres regeneracoes sem mudar conteudo mantem ${_i1} — a versao nao dispara sozinha"
  else record_fail "plugin-version-derived: (i)" "a versao andou sem mudanca de conteudo: ${_i1} ${_i2} ${_i3}"; fi
  rm -rf "$e"

  rm -rf "${d}"
}
_family run_plugin_version_derived_selftests

# Modo forge-detector — parseRepoIdentity do spec do forge (I_FORGE_PARSE_GITLAB_SUBGRUPOS, radar E3 rodada 3): a regex é
# EXTRAÍDA do próprio detector.md (não copiada) e exercitada em node; GitLab aninhado dá o namespace inteiro, GitHub 1 nível.
run_forge_detector_selftests() {
  local doc="${REPO_ROOT}/.claude/utils/forge/detector.md"
  [ -f "${doc}" ] || { record_fail "forge-detector" "detector.md ausente"; return; }
  command -v node >/dev/null 2>&1 || { record_skip "forge-detector: node ausente"; return; }
  local re; re="$(grep -oE 'remoteUrl\.match\(/.*/\);' "${doc}" | head -1 | sed -E 's/^remoteUrl\.match\(//; s/\);$//')"
  [ -n "${re}" ] || { record_fail "forge-detector: regex" "não achei remoteUrl.match(/…/) no detector.md"; return; }
  local out; out="$(RE="${re}" node -e '
const re = eval(process.env.RE);
for (const u of ["git@github.com:owner/repo.git","https://github.com/owner/repo","https://gitlab.com/group/project.git","https://gitlab.com/group/subgroup/project.git","git@gitlab.com:group/sub1/sub2/project.git"]) {
  const m = u.match(re); console.log(u + "\t" + (m ? m[1] + "\t" + m[2] : "null"));
}' 2>&1 || true)"
  if grep -qE $'^git@github.com:owner/repo.git\towner\trepo$' <<< "${out}"&& grep -qE $'^https://github.com/owner/repo\towner\trepo$' <<< "${out}"; then
    record_pass "forge-detector: (a) GitHub ssh/https ⇒ owner/repo (1 nível, inalterado)"
  else record_fail "forge-detector: (a) github" "$(_emit "${out}" | head -2 | tr '\n' '|')"; fi
  if grep -qE $'^https://gitlab.com/group/subgroup/project.git\tgroup/subgroup\tproject$' <<< "${out}"&& grep -qE $'^git@gitlab.com:group/sub1/sub2/project.git\tgroup/sub1/sub2\tproject$' <<< "${out}"; then
    record_pass "forge-detector: (b) GitLab aninhado ⇒ owner = namespace inteiro (group/subgroup; group/sub1/sub2)"
  else record_fail "forge-detector: (b) gitlab aninhado" "$(_emit "${out}" | tail -3 | tr '\n' '|')"; fi
}
_family run_forge_detector_selftests

# Modo marketplace-readmes — READMEs GERADOS no padrão de referência de plugins/marketplaces do Claude Code (2026-09-04):
# plugin-readme.sh (catálogo por plugin: comandos com namespace, agentes, skills, hooks, capability, proveniência) e
# marketplace-readme.sh (quick start slash+CLI, tabela de plugins com contagens, manter em dia, política de versão, moat).
# marketplace.json: entradas com displayName/category/tags/license e SEM version (plugin.json é a autoridade — docs oficiais).
run_marketplace_readmes_selftests() {
  local asm="${REPO_ROOT}/.claude/utils/marketplace/assemble-plugin.sh" mat="${REPO_ROOT}/.claude/utils/marketplace/materialize-marketplace-repo.sh"
  local prd="${REPO_ROOT}/.claude/utils/marketplace/plugin-readme.sh" mrd="${REPO_ROOT}/.claude/utils/marketplace/marketplace-readme.sh"
  for f in "${asm}" "${mat}" "${prd}" "${mrd}"; do [ -f "${f}" ] || { record_fail "marketplace-readmes" "ausente: ${f}"; return; }; done
  command -v python3 >/dev/null 2>&1 || { record_skip "marketplace-readmes: python3 ausente"; return; }
  local d out rc; d="$(mktemp -d)"
  mkdir -p "${d}/src/.claude/commands/quick" "${d}/src/.claude/agents/x" "${d}/src/.claude/utils/marketplace/verticals"
  printf -- '---\nname: ping\ndescription: Responde pong para provar a rota. Segunda frase que nao entra.\ncategory: quick\ntags: [a, b, c]\nversion: "1.0.0"\nupdated: "2026-09-04"\n---\n# ping\n' > "${d}/src/.claude/commands/quick/ping.md"
  printf -- '---\nname: probe-agent\ndescription: >\n  Agente de sonda que faz\n  duas linhas de descricao.\ncategory: development\ntags: [a, b, c]\nexpertise: [x, y, z]\nversion: "1.0.0"\nupdated: "2026-09-04"\n---\n# agente\n' > "${d}/src/.claude/agents/x/probe-agent.md"
  printf 'PLUGIN_NAME="probe"\nPLUGIN_VERSION="0.1.0"\nPLUGIN_DESC="Plugin de sonda da bancada"\nKEYWORDS=(probe sonda)\nCOMMANDS=(.claude/commands/quick/ping.md)\nAGENTS=(.claude/agents/x/probe-agent.md)\nUTILS=()\nVALIDATION=()\nTEMPLATES=()\nSKILLS=()\nHOOKS=()\nDOCS=()\n' > "${d}/src/.claude/utils/marketplace/verticals/probe.manifest.sh"
  ( cd "${d}/src" && git init -q && git add -A && git -c user.email=t@t -c user.name=t commit -qm seed ) >/dev/null 2>&1
  rc=0; bash "${asm}" "${d}/src/.claude/utils/marketplace/verticals/probe.manifest.sh" "${d}/src" "${d}/out" >/dev/null 2>&1 || rc=$?
  # (a) README do plugin: título, comando com namespace + 1ª frase da description, agente com description dobrada juntada, proveniência
  if [ "${rc}" -eq 0 ] && [ -f "${d}/out/README.md" ] && grep -qF '| `/probe:ping` | Responde pong para provar a rota. |' "${d}/out/README.md" \
     && grep -qF '| `@probe-agent` | Agente de sonda que faz duas linhas de descricao. |' "${d}/out/README.md" \
     && grep -q '^## Proveniência' "${d}/out/README.md" && grep -q 'tree_sha' "${d}/out/README.md"; then
    record_pass "marketplace-readmes: (a) README do plugin gerado: /probe:ping + 1ª frase, agente com description dobrada, proveniência"
  else record_fail "marketplace-readmes: (a) README do plugin" "rc=${rc}; $(grep -E 'probe:ping|probe-agent' "${d}/out/README.md" 2>/dev/null | head -2 | tr '\n' '|' | cut -c1-200)"; fi
  # (b) marketplace: materializar num alvo git com o plugin montado ⇒ README com tabela (linha do probe, contagens) e manifesto sem version
  mkdir -p "${d}/tgt/plugins"; ( cd "${d}/tgt" && git init -q ) >/dev/null 2>&1; cp -a "${d}/out" "${d}/tgt/plugins/probe"
  out="$(bash "${mrd}" "${d}/tgt" "mkt-probe" 2>&1 || true)"
  bash "${REPO_ROOT}/.claude/utils/marketplace/generate-marketplace.sh" "${d}/tgt" > "${d}/tgt/marketplace.json" 2>/dev/null || true
  # ⚠️ A VERSAO ESPERADA E DERIVADA, NAO LITERAL. A versao anterior deste caso travava `0.1.1` —
  #    numero da semantica antiga (contagem de commits). Quando a versao virou FATO COMMITADO o
  #    caso reprovou por conta de um literal, nao por defeito: ele afirmava o NUMERO em vez da
  #    PROPRIEDADE (a linha do marketplace mostra a versao real daquele plugin). Derivado, ele
  #    sobrevive a qualquer troca futura de mecanismo — e continua pegando a linha errada.
  local _mkv; _mkv="$(sed -n 's/.*"version"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' "${d}/tgt/plugins/probe/.claude-plugin/plugin.json" 2>/dev/null | head -1)"
  [ -n "${_mkv}" ] || _mkv="0.0.0-ausente"
  if grep -qE "^\| \[\`probe\`\]\(plugins/probe/README.md\) \| vertical \| \`${_mkv//./\\.}\` \| 1 \| 1 \| 0 \| 0 \|" "${d}/tgt/README.md" \
     && grep -q '/plugin marketplace add marciocar/mkt-probe' "${d}/tgt/README.md" && grep -q '^## Manter em dia' "${d}/tgt/README.md" \
     && python3 -c 'import json,sys; m=json.load(open(sys.argv[1])); e=m["plugins"][0]; sys.exit(0 if ("version" not in e and e.get("category")=="vertical" and e.get("tags")==["probe","sonda"] and e.get("displayName")) else 1)' "${d}/tgt/marketplace.json"; then
    record_pass "marketplace-readmes: (b) README do marketplace com tabela/contagens e manifesto: category+tags+displayName, SEM version por entrada"
  else record_fail "marketplace-readmes: (b) marketplace" "$(grep -E 'probe' "${d}/tgt/README.md" 2>/dev/null | head -1 | cut -c1-160) · $(head -c 200 "${d}/tgt/marketplace.json" 2>/dev/null | tr '\n' ' ')"; fi
  # (c) README do plugin NÃO é editado à mão: re-montar reescreve (artefato gerado)
  printf 'edicao manual\n' >> "${d}/out/README.md"
  bash "${asm}" "${d}/src/.claude/utils/marketplace/verticals/probe.manifest.sh" "${d}/src" "${d}/out" >/dev/null 2>&1 || true
  if ! grep -q 'edicao manual' "${d}/out/README.md"; then record_pass "marketplace-readmes: (c) re-montagem sobrescreve edição manual (artefato gerado)"
  else record_fail "marketplace-readmes: (c) gerado" "edição manual sobreviveu à re-montagem"; fi
  # (d) README é CONTENT-STABLE: um commit novo que NÃO toca as fontes (outro HEAD, outra data) gera README idêntico.
  #     Foi o drift que a REGRA 19 acusou no CI em 2026-09-04: ref/commit_date no README mudavam a cada commit.
  cp "${d}/out/README.md" "${d}/readme-head1.md"
  ( cd "${d}/src" && printf 'x\n' > unrelated.txt && git add unrelated.txt && GIT_COMMITTER_DATE="2030-01-01T00:00:00Z" git -c user.email=t@t -c user.name=t commit -qm other --date="2030-01-01T00:00:00Z" ) >/dev/null 2>&1
  bash "${asm}" "${d}/src/.claude/utils/marketplace/verticals/probe.manifest.sh" "${d}/src" "${d}/out2" >/dev/null 2>&1 || true
  if [ -f "${d}/out2/README.md" ] && cmp -s "${d}/readme-head1.md" "${d}/out2/README.md"; then record_pass "marketplace-readmes: (d) README content-stable entre HEADs (sem ref/data volátil)"
  else record_fail "marketplace-readmes: (d) content-stable" "README difere entre dois HEADs com as mesmas fontes: $(diff "${d}/readme-head1.md" "${d}/out2/README.md" 2>&1 | head -4 | tr '\n' ' ')"; fi
  # (e) LICENSE por plugin (exigência do diretório oficial): copia do source
  printf 'MIT License\n\nCopyright (c) 2026 Probe\n' > "${d}/src/LICENSE"
  bash "${asm}" "${d}/src/.claude/utils/marketplace/verticals/probe.manifest.sh" "${d}/src" "${d}/out" >/dev/null 2>&1 || true
  if [ -f "${d}/out/LICENSE" ] && grep -q 'Copyright (c) 2026 Probe' "${d}/out/LICENSE"; then record_pass "marketplace-readmes: (e) LICENSE do source embarcado em cada plugin"
  else record_fail "marketplace-readmes: (e) LICENSE" "ausente ou diferente do source"; fi
  rm -rf "${d}"
}
_family run_marketplace_readmes_selftests

# REGRA 72 — namespace de comando em plugin é /<plugin>:<cmd>. Helper plugin-namespace-check.sh
# (scan + cura --rewrite) e o wire-in no assembler (NAMESPACE-PORTABILITY). A bancada exercita o
# modo que a produção consome (`--format tsv`, REGRA 59) e o mutante (plugin editado à mão).
run_plugin_namespace_selftests() {
  local h="${REPO_ROOT}/.claude/validation/plugin-namespace-check.sh" asm="${REPO_ROOT}/.claude/utils/marketplace/assemble-plugin.sh"
  [ -f "${h}" ] && [ -f "${asm}" ] || { record_fail "plugin-namespace" "helper ou assembler ausente"; return; }
  command -v python3 >/dev/null 2>&1 || { record_skip "plugin-namespace: python3 ausente"; return; }
  local d out; d="$(mktemp -d)"
  export GIT_AUTHOR_NAME=t GIT_AUTHOR_EMAIL=t@t GIT_COMMITTER_NAME=t GIT_COMMITTER_EMAIL=t@t
  mkdir -p "${d}/src/.claude/commands/alpha" "${d}/src/.claude/commands/beta" "${d}/src/.claude/utils/marketplace/verticals"
  printf -- '---\nname: one\ndescription: Um. Rode /alpha:two, depois /beta:three e por fim /meta:adopt.\n---\n# one\nVeja `/alpha:two` (mesmo plugin), `/beta:three` (cross) e `/meta:adopt` (dangling). URL https://x/meta:nao fica.\n' > "${d}/src/.claude/commands/alpha/one.md"
  printf -- '---\nname: two\ndescription: Dois.\n---\n# two\n' > "${d}/src/.claude/commands/alpha/two.md"
  printf -- '---\nname: three\ndescription: Tres.\n---\n# three\n' > "${d}/src/.claude/commands/beta/three.md"
  printf 'PLUGIN_NAME="probe-a"\nPLUGIN_VERSION="0.1.0"\nPLUGIN_DESC="Sonda A"\nKEYWORDS=(a)\nCOMMANDS=(.claude/commands/alpha)\nAGENTS=()\nUTILS=()\nVALIDATION=()\nTEMPLATES=()\nSKILLS=()\nHOOKS=()\nDOCS=()\n' > "${d}/src/.claude/utils/marketplace/verticals/probe-a.manifest.sh"
  printf 'PLUGIN_NAME="probe-b"\nPLUGIN_VERSION="0.1.0"\nPLUGIN_DESC="Sonda B"\nKEYWORDS=(b)\nCOMMANDS=(.claude/commands/beta/three.md)\nAGENTS=()\nUTILS=()\nVALIDATION=()\nTEMPLATES=()\nSKILLS=()\nHOOKS=()\nDOCS=()\n' > "${d}/src/.claude/utils/marketplace/verticals/probe-b.manifest.sh"
  ( cd "${d}/src" && git init -q && git add -A && git commit -qm seed ) >/dev/null 2>&1
  # (a) o assembler CURA: mesmo-plugin e cross viram /<plugin>:<cmd>; dangling perde a barra; URL intacta
  bash "${asm}" "${d}/src/.claude/utils/marketplace/verticals/probe-a.manifest.sh" "${d}/src" "${d}/src/plugins/probe-a" >/dev/null 2>&1 || true
  out="$(cat "${d}/src/plugins/probe-a/commands/one.md" 2>/dev/null)"
  if grep -q '`/probe-a:two`' <<< "${out}" && grep -q '`/probe-b:three`' <<< "${out}" && grep -q '`meta:adopt`' <<< "${out}" && grep -q 'https://x/meta:nao' <<< "${out}" && ! grep -q '/alpha:two' <<< "${out}"; then
    record_pass "plugin-namespace: (a) assembler reescreve mesmo-plugin+cross para /<plugin>:<cmd>, dangling sem barra, URL intacta"
  else record_fail "plugin-namespace: (a) cura" "$(printf '%s' "${out}" | grep -n 'alpha:two\|beta:three\|meta:adopt' | head -3 | tr '\n' ' ')"; fi
  # (b) README lista os comandos do core citados e não distribuídos
  if grep -q '^## Comandos do core citados' "${d}/src/plugins/probe-a/README.md" 2>/dev/null && grep -q '`meta:adopt`' "${d}/src/plugins/probe-a/README.md"; then
    record_pass "plugin-namespace: (b) README lista meta:adopt como comando do core não distribuído"
  else record_fail "plugin-namespace: (b) README" "seção ausente ou sem meta:adopt"; fi
  # (c) o modo consumido pelo lint: --format tsv fica VAZIO no plugin curado
  out="$(bash "${h}" "${d}/src" --format tsv 2>/dev/null)"
  if [ -z "${out}" ]; then record_pass "plugin-namespace: (c) --format tsv vazio no plugin curado"
  else record_fail "plugin-namespace: (c) tsv" "$(printf '%s' "${out}" | head -2 | tr '\n' ' ')"; fi
  # (d) MUTANTE: plugin editado à mão volta ao namespace do core → 3 classes, HARD
  printf 'Rode /alpha:two, /beta:three e /meta:adopt.\n' >> "${d}/src/plugins/probe-a/commands/one.md"
  out="$(bash "${h}" "${d}/src" --format tsv 2>/dev/null)"
  if [ "$(printf '%s\n' "${out}" | grep -c '^HARD')" -eq 3 ] && grep -q 'mesmo-plugin' <<< "${out}" && grep -q 'cross-plugin' <<< "${out}" && grep -q 'dangling' <<< "${out}"; then
    record_pass "plugin-namespace: (d) mutante à mão → 3 HARD (mesmo-plugin, cross-plugin, dangling)"
  else record_fail "plugin-namespace: (d) mutante" "esperava 3 HARD: $(printf '%s' "${out}" | tr '\n' ' ' | cut -c1-200)"; fi
  # (e) idempotência: re-montar produz o mesmo arquivo (a cura não acumula)
  bash "${asm}" "${d}/src/.claude/utils/marketplace/verticals/probe-a.manifest.sh" "${d}/src" "${d}/src/plugins/probe-a" >/dev/null 2>&1 || true
  cp "${d}/src/plugins/probe-a/commands/one.md" "${d}/one-1.md"
  bash "${asm}" "${d}/src/.claude/utils/marketplace/verticals/probe-a.manifest.sh" "${d}/src" "${d}/src/plugins/probe-a" >/dev/null 2>&1 || true
  if cmp -s "${d}/one-1.md" "${d}/src/plugins/probe-a/commands/one.md"; then record_pass "plugin-namespace: (e) re-montagem idempotente"
  else record_fail "plugin-namespace: (e) idempotência" "$(diff "${d}/one-1.md" "${d}/src/plugins/probe-a/commands/one.md" | head -3 | tr '\n' ' ')"; fi
  unset GIT_AUTHOR_NAME GIT_AUTHOR_EMAIL GIT_COMMITTER_NAME GIT_COMMITTER_EMAIL
  rm -rf "${d}"
}
_family run_plugin_namespace_selftests

# REGRA 73 — hook empacotado resolve no plugin instalado (helper plugin-hooks-check.sh) + o gerador de
# hooks.json carrega o matcher do core. Exercita o modo consumido (`--format tsv`, REGRA 59) e o mutante.
run_plugin_hooks_resolvable_selftests() {
  local h="${REPO_ROOT}/.claude/validation/plugin-hooks-check.sh" asm="${REPO_ROOT}/.claude/utils/marketplace/assemble-plugin.sh"
  [ -f "${h}" ] && [ -f "${asm}" ] || { record_fail "plugin-hooks-resolvable" "helper ou assembler ausente"; return; }
  command -v python3 >/dev/null 2>&1 || { record_skip "plugin-hooks-resolvable: python3 ausente"; return; }
  local d out; d="$(mktemp -d)"
  export GIT_AUTHOR_NAME=t GIT_AUTHOR_EMAIL=t@t GIT_COMMITTER_NAME=t GIT_COMMITTER_EMAIL=t@t
  mkdir -p "${d}/src/.claude/hooks" "${d}/src/.claude/validation" "${d}/src/.claude/utils/marketplace/verticals"
  printf '#!/usr/bin/env bash\nHERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"\nENGINE="${HERE}/../validation/engine.sh"\n[ -f "$ENGINE" ] || exit 0\nexit 0\n' > "${d}/src/.claude/hooks/g.sh"; chmod +x "${d}/src/.claude/hooks/g.sh"
  printf '#!/usr/bin/env bash\nexit 0\n' > "${d}/src/.claude/validation/engine.sh"
  printf '{"hooks":{"PostToolUse":[{"matcher":"Bash","hooks":[{"type":"command","command":"bash \\"$CLAUDE_PROJECT_DIR/.claude/hooks/g.sh\\""}]}]}}\n' > "${d}/src/.claude/settings.json"
  printf 'PLUGIN_NAME="hp"\nPLUGIN_VERSION="0.1.0"\nPLUGIN_DESC="x"\nKEYWORDS=(x)\nCOMMANDS=()\nAGENTS=()\nUTILS=()\nVALIDATION=(.claude/validation/engine.sh)\nTEMPLATES=()\nSKILLS=()\nHOOKS=(.claude/hooks/g.sh)\nDOCS=()\n' > "${d}/src/.claude/utils/marketplace/verticals/hp.manifest.sh"
  ( cd "${d}/src" && git init -q && git add -A && git commit -qm seed ) >/dev/null 2>&1
  bash "${asm}" "${d}/src/.claude/utils/marketplace/verticals/hp.manifest.sh" "${d}/src" "${d}/src/plugins/hp" >/dev/null 2>&1 || true
  # (a) hooks.json gerado carrega o matcher do core
  if grep -q '"matcher": "Bash"' "${d}/src/plugins/hp/hooks/hooks.json" 2>/dev/null; then record_pass "plugin-hooks-resolvable: (a) hooks.json gerado carrega o matcher do core"
  else record_fail "plugin-hooks-resolvable: (a) matcher" "$(cat "${d}/src/plugins/hp/hooks/hooks.json" 2>/dev/null | tr -d '\n ' | cut -c1-160)"; fi
  # (b) modo consumido: --format tsv vazio no plugin correto
  out="$(bash "${h}" "${d}/src" --format tsv 2>/dev/null)"
  if [ -z "${out}" ]; then record_pass "plugin-hooks-resolvable: (b) --format tsv vazio (hook + motor + matcher resolvem)"
  else record_fail "plugin-hooks-resolvable: (b) tsv" "$(printf '%s' "${out}" | head -2 | tr '\n' ' ' | cut -c1-200)"; fi
  # (c) mutante: motor removido + caminho $REPO/${CLAUDE_PLUGIN_ROOT} + matcher perdido → 3 classes HARD
  rm -f "${d}/src/plugins/hp/validation/engine.sh"
  printf 'ENGINE="$REPO/${CLAUDE_PLUGIN_ROOT}/validation/engine.sh"\n' >> "${d}/src/plugins/hp/hooks/g.sh"
  sed -i 's/"matcher": "Bash",//' "${d}/src/plugins/hp/hooks/hooks.json"
  out="$(bash "${h}" "${d}/src" --format tsv 2>/dev/null)"
  if printf '%s' "${out}" | grep -q "motor-ausente" && printf '%s' "${out}" | grep -q "repo-prefixado" && printf '%s' "${out}" | grep -q "matcher-divergente"; then
    record_pass "plugin-hooks-resolvable: (c) mutante → motor-ausente + repo-prefixado + matcher-divergente"
  else record_fail "plugin-hooks-resolvable: (c) mutante" "$(printf '%s' "${out}" | tr '\n' ' ' | cut -c1-240)"; fi
  unset GIT_AUTHOR_NAME GIT_AUTHOR_EMAIL GIT_COMMITTER_NAME GIT_COMMITTER_EMAIL
  rm -rf "${d}"
}
_family run_plugin_hooks_resolvable_selftests

# REGRA 74 — caminho .claude/ NU dentro de plugin, com catraca (helper plugin-bare-path-check.sh).
# Modo consumido `--format tsv`; baseline via --emit-baseline; NOVO fora do baseline = HARD.
run_plugin_bare_path_selftests() {
  local h="${REPO_ROOT}/.claude/validation/plugin-bare-path-check.sh"
  [ -f "${h}" ] || { record_fail "plugin-bare-path" "helper ausente"; return; }
  command -v python3 >/dev/null 2>&1 || { record_skip "plugin-bare-path: python3 ausente"; return; }
  local d out; d="$(mktemp -d)"
  mkdir -p "${d}/r/.claude/validation" "${d}/r/plugins/p/commands"
  printf -- '---\nname: x\nallowed-tools: Bash(bash .claude/utils/co/relay.sh*)\n---\nVeja `.claude/utils/c4-templates.md`, `${CLAUDE_PLUGIN_ROOT}/utils/ok.md` e `.claude/sessions/x`.\n' > "${d}/r/plugins/p/commands/x.md"
  # (a) sem baseline → NO-BASELINE + 2 NOVO (sessions/ e PLUGIN_ROOT não contam)
  out="$(bash "${h}" "${d}/r" --format tsv 2>/dev/null)"
  if printf '%s' "${out}" | grep -q "NO-BASELINE" && [ "$(printf '%s\n' "${out}" | grep -c "	NOVO	")" -eq 2 ]; then record_pass "plugin-bare-path: (a) sem baseline = NO-BASELINE + 2 NOVO (sessions/ e PLUGIN_ROOT não contam)"
  else record_fail "plugin-bare-path: (a)" "$(printf '%s' "${out}" | tr '\n' ' ' | cut -c1-200)"; fi
  # (b) baseline emitido → passivo SOFT, allowed-tools sinalizado, 0 HARD
  bash "${h}" "${d}/r" --emit-baseline > "${d}/r/.claude/validation/plugin-bare-path-baseline.txt"
  out="$(bash "${h}" "${d}/r" --format tsv 2>/dev/null)"
  if ! printf '%s' "${out}" | grep -q "^HARD" && printf '%s' "${out}" | grep -q "ALLOWED-TOOLS" && printf '%s' "${out}" | grep -q "PASSIVO"; then record_pass "plugin-bare-path: (b) passivo baselined = SOFT; allowed-tools sinalizado"
  else record_fail "plugin-bare-path: (b)" "$(printf '%s' "${out}" | tr '\n' ' ' | cut -c1-200)"; fi
  # (c) ref NOVA fora do baseline = HARD
  printf 'Nova: `.claude/commands/common/templates/t.md`.\n' >> "${d}/r/plugins/p/commands/x.md"
  out="$(bash "${h}" "${d}/r" --format tsv 2>/dev/null)"
  if printf '%s' "${out}" | grep -q "^HARD	NOVO"; then record_pass "plugin-bare-path: (c) ref nova fora do baseline = HARD"
  else record_fail "plugin-bare-path: (c)" "$(printf '%s' "${out}" | tr '\n' ' ' | cut -c1-200)"; fi
  rm -rf "${d}"
}
_family run_plugin_bare_path_selftests

# REGRA 75 — link relativo morto em plugin (helper plugin-dead-link-check.sh + cura --rewrite no assembler).
# Modo consumido `--format tsv` (REGRA 59) e mutante (plugin editado à mão).
run_plugin_dead_link_selftests() {
  local h="${REPO_ROOT}/.claude/validation/plugin-dead-link-check.sh" asm="${REPO_ROOT}/.claude/utils/marketplace/assemble-plugin.sh"
  [ -f "${h}" ] && [ -f "${asm}" ] || { record_fail "plugin-dead-link" "helper ou assembler ausente"; return; }
  command -v python3 >/dev/null 2>&1 || { record_skip "plugin-dead-link: python3 ausente"; return; }
  local d out; d="$(mktemp -d)"
  export GIT_AUTHOR_NAME=t GIT_AUTHOR_EMAIL=t@t GIT_COMMITTER_NAME=t GIT_COMMITTER_EMAIL=t@t
  mkdir -p "${d}/src/.claude/commands/alpha" "${d}/src/.claude/utils/marketplace/verticals" "${d}/src/docs/kb"
  printf 'viva\n' > "${d}/src/docs/kb/viva.md"; printf 'morta\n' > "${d}/src/docs/kb/morta.md"
  printf -- '---\nname: one\ndescription: Um.\n---\nVeja [viva](../../../docs/kb/viva.md), [morta](../../../docs/kb/morta.md) e [url](https://x/y.md).\n' > "${d}/src/.claude/commands/alpha/one.md"
  printf 'PLUGIN_NAME="dl"\nPLUGIN_VERSION="0.1.0"\nPLUGIN_DESC="x"\nKEYWORDS=(x)\nCOMMANDS=(.claude/commands/alpha)\nAGENTS=()\nUTILS=()\nVALIDATION=()\nTEMPLATES=()\nSKILLS=()\nHOOKS=()\nDOCS=(docs/kb/viva.md)\n' > "${d}/src/.claude/utils/marketplace/verticals/dl.manifest.sh"
  ( cd "${d}/src" && git init -q && git add -A && git commit -qm seed ) >/dev/null 2>&1
  bash "${asm}" "${d}/src/.claude/utils/marketplace/verticals/dl.manifest.sh" "${d}/src" "${d}/src/plugins/dl" >/dev/null 2>&1 || true
  out="$(cat "${d}/src/plugins/dl/commands/one.md" 2>/dev/null)"
  # (a) a cura: a irmã embarcada (viva → kb/) segue link; a não-embarcada vira texto; URL intacta
  if grep -q 'kb/viva.md' <<< "${out}" && grep -q ' morta ' <<< "${out}" && grep -q '\[url\](https://x/y.md)' <<< "${out}"; then
    record_pass "plugin-dead-link: (a) assembler: irmã embarcada mantém link, não-embarcada vira texto, URL intacta"
  else record_fail "plugin-dead-link: (a) cura" "$(printf '%s' "${out}" | tail -1 | cut -c1-200)"; fi
  # (b) modo consumido: --format tsv vazio no plugin curado
  out="$(bash "${h}" "${d}/src" --format tsv 2>/dev/null)"
  if [ -z "${out}" ]; then record_pass "plugin-dead-link: (b) --format tsv vazio no plugin curado"
  else record_fail "plugin-dead-link: (b) tsv" "$(printf '%s' "${out}" | head -2 | tr '\n' ' ' | cut -c1-200)"; fi
  # (c) mutante: link morto reintroduzido à mão → HARD; templates/ não conta
  printf 'De novo: [morta](../kb/morta.md)\n' >> "${d}/src/plugins/dl/commands/one.md"
  mkdir -p "${d}/src/plugins/dl/templates"; printf '[gera](../docs/x.md)\n' > "${d}/src/plugins/dl/templates/t.md"
  out="$(bash "${h}" "${d}/src" --format tsv 2>/dev/null)"
  if [ "$(printf '%s\n' "${out}" | grep -c '^HARD')" -eq 1 ] && grep -q 'morta.md' <<< "${out}"; then record_pass "plugin-dead-link: (c) mutante → 1 HARD; templates/ fora por desenho"
  else record_fail "plugin-dead-link: (c) mutante" "$(printf '%s' "${out}" | tr '\n' ' ' | cut -c1-200)"; fi
  unset GIT_AUTHOR_NAME GIT_AUTHOR_EMAIL GIT_COMMITTER_NAME GIT_COMMITTER_EMAIL
  rm -rf "${d}"
}
_family run_plugin_dead_link_selftests

# REGRA 76 — marketplace.json da raiz == gerador (helper marketplace-root-check.sh; --write seguro).
run_marketplace_root_sync_selftests() {
  local h="${REPO_ROOT}/.claude/validation/marketplace-root-check.sh"
  [ -f "${h}" ] || { record_fail "marketplace-root-sync" "helper ausente"; return; }
  local d out; d="$(mktemp -d)"
  mkdir -p "${d}/r/.claude-plugin" "${d}/r/plugins/probe/.claude-plugin"
  printf '{\n  "name": "probe",\n  "version": "0.1.3",\n  "description": "Sonda",\n  "author": { "name": "t" },\n  "keywords": ["a"],\n  "license": "MIT",\n  "homepage": "https://x",\n  "repository": "https://x"\n}\n' > "${d}/r/plugins/probe/.claude-plugin/plugin.json"
  printf '{\n  "name": "probe-mkt",\n  "owner": { "name": "t" },\n  "plugins": []\n}\n' > "${d}/r/.claude-plugin/marketplace.json"
  # (a) stale → HARD (modo consumido --format tsv)
  out="$(bash "${h}" "${d}/r" --format tsv 2>/dev/null)"
  if grep -q '^HARD	desatualizado' <<< "${out}"; then record_pass "marketplace-root-sync: (a) marketplace.json stale → HARD"
  else record_fail "marketplace-root-sync: (a)" "$(printf '%s' "${out}" | cut -c1-200)"; fi
  # (b) --write regenera com top-level preservado → limpo
  bash "${h}" "${d}/r" --write >/dev/null 2>&1
  out="$(bash "${h}" "${d}/r" --format tsv 2>/dev/null)"
  if [ -z "${out}" ] && grep -q '"probe-mkt"' "${d}/r/.claude-plugin/marketplace.json" && grep -q '"probe"' "${d}/r/.claude-plugin/marketplace.json"; then record_pass "marketplace-root-sync: (b) --write regenera (temp+mv), top-level preservado, limpo"
  else record_fail "marketplace-root-sync: (b)" "$(printf '%s' "${out}" | cut -c1-200)"; fi
  rm -rf "${d}"
}
_family run_marketplace_root_sync_selftests

# REGRA 77 — contrato de dependência entre plugins (helper plugin-deps-check.sh; REQUIRES_PLUGINS no assembler;
# README "Requer"/"Funciona melhor com"). Modo consumido `--format tsv` (REGRA 59) e mutantes.
run_plugin_deps_contract_selftests() {
  local h="${REPO_ROOT}/.claude/validation/plugin-deps-check.sh" asm="${REPO_ROOT}/.claude/utils/marketplace/assemble-plugin.sh"
  [ -f "${h}" ] && [ -f "${asm}" ] || { record_fail "plugin-deps-contract" "helper ou assembler ausente"; return; }
  command -v python3 >/dev/null 2>&1 || { record_skip "plugin-deps-contract: python3 ausente"; return; }
  local d out; d="$(mktemp -d)"
  export GIT_AUTHOR_NAME=t GIT_AUTHOR_EMAIL=t@t GIT_COMMITTER_NAME=t GIT_COMMITTER_EMAIL=t@t
  mkdir -p "${d}/src/.claude/commands/alpha" "${d}/src/.claude/commands/beta" "${d}/src/.claude/skills/orch" "${d}/src/.claude/utils/marketplace/verticals"
  printf -- '---\nname: orch\ndescription: Orquestra.\n---\n' > "${d}/src/.claude/skills/orch/SKILL.md"
  printf -- '---\nname: one\ndescription: Um.\n---\nUsa a skill skills/orch e cita /beta:three.\n' > "${d}/src/.claude/commands/alpha/one.md"
  printf -- '---\nname: three\ndescription: Tres.\n---\n' > "${d}/src/.claude/commands/beta/three.md"
  printf 'PLUGIN_NAME="onion"\nPLUGIN_VERSION="0.1.0"\nPLUGIN_DESC="core"\nKEYWORDS=(a)\nCOMMANDS=(.claude/commands/beta/three.md)\nAGENTS=()\nUTILS=()\nVALIDATION=()\nTEMPLATES=()\nSKILLS=(.claude/skills/orch)\nHOOKS=()\nDOCS=()\n' > "${d}/src/.claude/utils/marketplace/verticals/onion.manifest.sh"
  printf 'PLUGIN_NAME="onion-x"\nPLUGIN_VERSION="0.1.0"\nPLUGIN_DESC="x"\nKEYWORDS=(x)\nCOMMANDS=(.claude/commands/alpha)\nAGENTS=()\nUTILS=()\nVALIDATION=()\nTEMPLATES=()\nSKILLS=()\nHOOKS=()\nDOCS=()\nREQUIRES_PLUGINS=(onion)\n' > "${d}/src/.claude/utils/marketplace/verticals/onion-x.manifest.sh"
  ( cd "${d}/src" && git init -q && git add -A && git commit -qm seed ) >/dev/null 2>&1
  for p in onion onion-x; do bash "${asm}" "${d}/src/.claude/utils/marketplace/verticals/${p}.manifest.sh" "${d}/src" "${d}/src/plugins/${p}" >/dev/null 2>&1 || true; done
  # (a) REQUIRES_PLUGINS → capability.json plugin:onion + README "Requer"; menção de comando → "Funciona melhor com" NÃO (é dependência declarada)
  if grep -q '"plugin:onion"' "${d}/src/plugins/onion-x/.claude-plugin/capability.json" 2>/dev/null && grep -q '^## Requer' "${d}/src/plugins/onion-x/README.md" && grep -q '`onion`' "${d}/src/plugins/onion-x/README.md"; then
    record_pass "plugin-deps-contract: (a) REQUIRES_PLUGINS vira plugin:<x> no capability.json e seção Requer no README"
  else record_fail "plugin-deps-contract: (a)" "$(cat "${d}/src/plugins/onion-x/.claude-plugin/capability.json" 2>/dev/null | tr -d '\n ' | cut -c1-160)"; fi
  # (b) modo consumido: --format tsv limpo com o contrato coerente
  out="$(bash "${h}" "${d}/src" --format tsv 2>/dev/null)"
  if [ -z "${out}" ]; then record_pass "plugin-deps-contract: (b) --format tsv vazio com contrato coerente"
  else record_fail "plugin-deps-contract: (b) tsv" "$(printf '%s' "${out}" | head -2 | tr '\n' ' ' | cut -c1-200)"; fi
  # (c) mutante 1: some a declaração → skill de outro plugin sem REQUIRES_PLUGINS = HARD; menção de comando = SOFT
  printf 'PLUGIN_NAME="onion-x"\nCOMMANDS=(.claude/commands/alpha)\n' > "${d}/src/.claude/utils/marketplace/verticals/onion-x.manifest.sh"
  out="$(bash "${h}" "${d}/src" --format tsv 2>/dev/null)"
  if grep -q '^HARD	dependencia-nao-declarada' <<< "${out}"; then record_pass "plugin-deps-contract: (c) skill de outro plugin sem REQUIRES_PLUGINS → HARD"
  else record_fail "plugin-deps-contract: (c) mutante" "$(printf '%s' "${out}" | tr '\n' ' ' | cut -c1-200)"; fi
  # (d) mutante 2: conhecimento duplicado (a mesma skill nos dois plugins) → HARD duplicado
  mkdir -p "${d}/src/plugins/onion-x/skills/orch"; cp "${d}/src/plugins/onion/skills/orch/SKILL.md" "${d}/src/plugins/onion-x/skills/orch/SKILL.md"
  out="$(bash "${h}" "${d}/src" --format tsv 2>/dev/null)"
  if grep -q '^HARD	duplicado' <<< "${out}"; then record_pass "plugin-deps-contract: (d) skill duplicada em 2 plugins → HARD duplicado"
  else record_fail "plugin-deps-contract: (d) duplicado" "$(printf '%s' "${out}" | tr '\n' ' ' | cut -c1-200)"; fi
  unset GIT_AUTHOR_NAME GIT_AUTHOR_EMAIL GIT_COMMITTER_NAME GIT_COMMITTER_EMAIL
  rm -rf "${d}"
}
_family run_plugin_deps_contract_selftests

# Três curas de sinal upstream (2026-09-04): enumeração rastreada no inventário,
# .claude/workflows na superfície de adoção, e assunto de commit em pt-BR no durable-commit.
run_upstream_portal_fixes_selftests() {
  local inv="${SCRIPT_DIR}/inventory.sh" dc="${SCRIPT_DIR}/../utils/adopt/durable-commit.sh"
  local vb="${SCRIPT_DIR}/../utils/adopt/vendor-branch.sh" adopt="${SCRIPT_DIR}/../commands/meta/adopt.md"
  command -v git >/dev/null 2>&1 || { record_skip "upstream-portal: git ausente"; return; }

  # ── (a) INVENTÁRIO conta só o RASTREADO: arquivo gitignorado não infla a contagem (lint local = CI) ──
  if [ ! -f "${inv}" ]; then record_skip "upstream-portal: (a) inventory.sh ausente"; else
    local sb; sb="$(mktemp -d)"; sb="$(cd "${sb}" && pwd -P)"
    mkdir -p "${sb}/.claude/validation" "${sb}/.claude/agents/development" "${sb}/.claude/commands/meta" \
             "${sb}/.claude/skills/foo" "${sb}/docs/onion" "${sb}/docs/knowledge-base/concepts"
    cp "${SCRIPT_DIR}"/*.sh "${sb}/.claude/validation/" 2>/dev/null
    printf -- '---\nname: foo\ndescription: x\n---\n# s\n' > "${sb}/.claude/skills/foo/SKILL.md"
    printf '# kb\n' > "${sb}/docs/knowledge-base/concepts/k.md"
    printf -- '---\ndescription: x\n---\n# c\n' > "${sb}/.claude/commands/meta/c.md"
    printf -- '---\nname: visivel\ndescription: x\nmodel: sonnet\ncategory: development\n---\nrole\n' > "${sb}/.claude/agents/development/visivel.md"
    printf -- '---\nname: ignorado\ndescription: x\nmodel: sonnet\ncategory: development\n---\nrole\n' > "${sb}/.claude/agents/development/ignorado.md"
    printf '.claude/agents/development/ignorado.md\n' > "${sb}/.gitignore"
    git -C "${sb}" init -q; git -C "${sb}" add -A >/dev/null 2>&1
    git -C "${sb}" -c user.name=t -c user.email=t@t commit -q -m seed >/dev/null 2>&1
    local out n_ag
    out="$(cd "${sb}" && bash .claude/validation/inventory.sh --markdown 2>/dev/null || true)"
    # o inventário imprime a linha `| Agentes | **N** |` (formato real, conferido em docs/onion/inventory.md)
    n_ag="$(grep -oE '^\| Agentes \| \*\*[0-9]+\*\*' <<< "${out}" 2>/dev/null | grep -oE '[0-9]+' | head -1 || true)"
    if [ "${n_ag:-x}" = "1" ]; then
      record_pass "upstream-portal: (a) inventário conta só o RASTREADO — arquivo gitignorado fora (lint local = CI)"
    else
      record_fail "upstream-portal: (a) enumeração rastreada" "esperava 1 agente (o gitignorado fora), leu '${n_ag:-vazio}'; find veria $(find "${sb}/.claude/agents" -name '*.md' | grep -c . || true)"
    fi
    rm -rf "${sb}"
  fi

  # ── (b) .claude/workflows viaja na adoção: sem ele a skill onion-research aponta p/ script ausente ──
  local miss=""
  # Desde 2026-09-14 a lista NÃO mora mais nos consumidores: SSOT em vendor-manifest.sh. Asserir o
  # literal `want=(` aqui mediria a CÓPIA, não o transporte — e foi o que reprovou quando a SSOT nasceu.
  # Agora a pergunta certa: o transporte EMITE .claude/workflows, e os dois consumidores o CONSOMEM?
  local vmsh="${REPO_ROOT}/.claude/utils/adopt/vendor-manifest.sh"
  # ⚠️ SEM PIPE PARA O `grep -q` — a forma anterior (`… --emit-scrub-roots | grep -qx …`) é uma
  # CORRIDA, e ela REPROVOU este caso ao vivo em 2026-09-14: `.claude/workflows` é a 8ª de 11
  # linhas, então o `grep -qx` casa e SAI enquanto o `printf '%s\n' "${_base[@]}"` do manifesto
  # ainda tem 3 linhas para escrever — SIGPIPE, saída 141, `pipefail` propaga, e o `!` transforma
  # a falha de pipe em "fora da superfície". A guarda acusou o transporte de não carregar um
  # diretório que ele carrega. Mesma classe curada no `lint-artifacts.sh` neste mesmo commit
  # ([[pipefail-epipe-early-closer-class]]); capturar em variável não tem leitor que feche cedo.
  local _roots=""
  if [ ! -f "${vmsh}" ]; then miss="${miss} vendor-manifest.sh(SSOT ausente)"
  else
    _roots="$(bash "${vmsh}" --emit-scrub-roots 2>/dev/null)" || _roots=""
    grep -qx '.claude/workflows' <<< "${_roots}" || miss="${miss} vendor-manifest.sh(.claude/workflows fora da superfície)"
  fi
  grep -q 'vendor-manifest.sh' "${vb}" 2>/dev/null || miss="${miss} vendor-branch.sh(não consome a SSOT)"
  grep -q 'vendor-manifest.sh' "${adopt}" 2>/dev/null || miss="${miss} adopt.md(não consome a SSOT)"
  if [ -z "${miss}" ]; then
    record_pass "upstream-portal: (b) .claude/workflows na superfície de adoção (a skill onion-research resolve no adotante)"
  else
    record_fail "upstream-portal: (b) workflows não viaja" "ausente em:${miss} — a skill instrui scriptPath '.claude/workflows/onion-research.js' e o comando nasce morto no adotante"
  fi

  # ── (c) durable-commit: assunto em pt-BR por default, SUBJECT= sobrepõe (prefixo Conventional intacto) ──
  if [ ! -f "${dc}" ]; then record_skip "upstream-portal: (c) durable-commit.sh ausente"; else
    local t; t="$(mktemp -d)"; t="$(cd "${t}" && pwd -P)"
    # IDENTIDADE GIT POR ENV: o durable-commit faz o PRÓPRIO `git commit` e o runner do CI não tem
    # user.email global — sem isto o helper sai 1 e, sob `set -e`, MATA a suíte (medido no CI do #805,
    # 6ª ocorrência da classe "a bancada espelha o runner"; local passava por ter identidade global).
    export GIT_AUTHOR_NAME=t GIT_AUTHOR_EMAIL=t@t GIT_COMMITTER_NAME=t GIT_COMMITTER_EMAIL=t@t
    git -C "${t}" init -q; mkdir -p "${t}/.claude"; printf 'x\n' > "${t}/.claude/marca.txt"
    git -C "${t}" commit -q --allow-empty -m base >/dev/null 2>&1 || true
    bash "${dc}" "${t}" adopt abc1234 main >/dev/null 2>&1 || true
    local subj; subj="$(git -C "${t}" log -1 --pretty=%s 2>/dev/null || true)"
    if [ "${subj}" = "chore(onion): adotar o Onion no pin abc1234" ]; then
      record_pass "upstream-portal: (c) durable-commit emite assunto em pt-BR (prefixo Conventional em inglês, assunto narrativo)"
    else
      record_fail "upstream-portal: (c) idioma do assunto" "esperava 'chore(onion): adotar o Onion no pin abc1234', veio '${subj}'"
    fi
    printf 'y\n' > "${t}/.claude/marca2.txt"
    SUBJECT="assunto do alvo" bash "${dc}" "${t}" adopt abc1234 main >/dev/null 2>&1 || true
    subj="$(git -C "${t}" log -1 --pretty=%s 2>/dev/null || true)"
    if [ "${subj}" = "chore(onion): assunto do alvo" ]; then
      record_pass "upstream-portal: (c2) SUBJECT= sobrepõe (alvo com política própria)"
    else
      record_fail "upstream-portal: (c2) SUBJECT=" "esperava 'chore(onion): assunto do alvo', veio '${subj}'"
    fi
    unset GIT_AUTHOR_NAME GIT_AUTHOR_EMAIL GIT_COMMITTER_NAME GIT_COMMITTER_EMAIL
    rm -rf "${t}"
  fi

  # (c3) CLASSE, não caso: TODA mensagem de commit/merge dos utils de adoção tem assunto em pt-BR.
  #      A cura de (c) parou no `durable-commit.sh` e o `vendor-branch.sh` seguiu emitindo
  #      "update to pin <x>" — o commit que o adotante mais vê na própria história, e ele apareceu
  #      no 1º `--update` real de um greenfield (2026-09-05). A cura cobriu o EXEMPLO, não a CLASSE.
  local _msgs _en=""
  _msgs="$(grep -rhE '(commit|merge)[^|]*-m "chore\(onion\): [^"]*"' "${SCRIPT_DIR}/../utils/adopt/"*.sh 2>/dev/null | grep -vE '^[[:space:]]*#' || true)"
  while IFS= read -r _l; do
    [ -n "${_l}" ] || continue
    # prefixo Conventional é INGLÊS por contrato; o ASSUNTO é pt-BR. Verbo inglês logo após o `: ` acusa.
    grep -qE 'chore\(onion\): (update|adopt|seed|apply|install|sync|promote|decouple) ' <<< "${_l}" \
      && _en="${_en} $(cut -c1-70 <<< "${_l}")"
  done <<< "${_msgs}"
  if [ -z "${_en}" ]; then
    record_pass "upstream-portal: (c3) CLASSE — nenhum assunto de commit/merge dos utils de adoção em INGLÊS"
  else
    record_fail "upstream-portal: (c3) idioma do assunto (classe)" "assunto em inglês (o prefixo é contrato de máquina; o ASSUNTO é narrativa pt-BR — code-standards §3.4):${_en}"
  fi

  # ── (d) a FILA kg-inbox nasce na adoção: o bloco (2a) do starter é EXECUTADO num sandbox ────────
  #     Não basta grepar a prosa do adopt.md — "guarda que valida prosa não é guarda". Extraímos o
  #     bloco e rodamos: o que se prova é o EFEITO (README + _sealed/ + _rejected/), e a 2ª rodada
  #     prova a idempotência (o starter não clobba fila em uso).
  if [ ! -f "${adopt}" ]; then record_skip "upstream-portal: (d) adopt.md ausente"; else
    local sd blk; sd="$(mktemp -d)"; sd="$(cd "${sd}" && pwd -P)"
    blk="$(awk '/^# \(2a\) fila de PROPOSTAS/{f=1} /^# \(2b\) semente de PESQUISA/{f=0} f' "${adopt}")"
    local blk_n; blk_n="$(printf '%s\n' "${blk}" | grep -c . || true)"
    if [ -n "${blk}" ] && { [ "${blk_n}" -gt 12 ] || ! grep -q 'starter-kg-inbox.sh' <<< "${blk}"; }; then
      record_fail "upstream-portal: (d) fatia do starter deriva de sentinela alheia" \
        "a extração entre '(2a)' e '(2b)' devolveu ${blk_n} linha(s)$(grep -q 'starter-kg-inbox.sh' <<< "${blk}" || printf ' e SEM a chamada do helper') — confira a sentinela: renomear o comentário do bloco seguinte faz a fatia engolir o resto do adopt.md"
      blk=""
    fi
    if [ -z "${blk}" ]; then
      record_fail "upstream-portal: (d) fila kg-inbox no starter da adoção" \
        "bloco '(2a) fila de PROPOSTAS' não encontrado em adopt.md — o /meta:kg-inbox roteado por papel não tem onde operar no dia 1 do adotante"
    else
      DEST="${sd}" SOURCE_ROOT="${SCRIPT_DIR}/../.." bash -c "${blk}" >/dev/null 2>&1 || true
      printf 'marca do adotante\n' >> "${sd}/docs/evolution/kg-inbox/README.md" 2>/dev/null || true
      DEST="${sd}" SOURCE_ROOT="${SCRIPT_DIR}/../.." bash -c "${blk}" >/dev/null 2>&1 || true   # 2ª passada: idempotente
      local dmiss=""
      [ -f "${sd}/docs/evolution/kg-inbox/README.md" ] || dmiss="${dmiss} README.md"
      [ -d "${sd}/docs/evolution/kg-inbox/_sealed" ]   || dmiss="${dmiss} _sealed/"
      [ -d "${sd}/docs/evolution/kg-inbox/_rejected" ] || dmiss="${dmiss} _rejected/"
      grep -q 'marca do adotante' "${sd}/docs/evolution/kg-inbox/README.md" 2>/dev/null || dmiss="${dmiss} idempotência(clobbou o README em uso)"
      if [ -z "${dmiss}" ]; then
        record_pass "upstream-portal: (d) a fila kg-inbox NASCE na adoção (bloco executado; 2ª passada idempotente)"
      else
        record_fail "upstream-portal: (d) fila kg-inbox no starter da adoção" "ausente/quebrado após executar o bloco:${dmiss}"
      fi
    fi
    rm -rf "${sd}"
  fi

  # ── (d2) fail-CLOSED de verdade: o helper CONFERE o efeito e o chamador LÊ o rc ──────────────────
  #     `exit 0` é declaração do script sobre si; a verificação é contar o que ele produziu. Sem isto,
  #     um DEST read-only fazia a adoção seguir e o adotante nascer SEM fila, sem nada a jusante conferir.
  local kh="${SCRIPT_DIR}/../utils/adopt/starter-kg-inbox.sh"
  if [ ! -f "${kh}" ]; then record_skip "upstream-portal: (d2) starter-kg-inbox.sh ausente"; else
    local ro rc2 d2miss=""
    ro="$(mktemp -d)"; mkdir -p "${ro}/docs"; chmod -w "${ro}/docs"
    bash "${kh}" "${ro}" >/dev/null 2>&1 && rc2=0 || rc2=1
    chmod +w "${ro}/docs"; rm -rf "${ro}"
    [ "${rc2}" -ne 0 ] || d2miss="${d2miss} helper-sai-0-sem-criar-a-fila(DEST somente-leitura)"
    local _call; _call="$(grep -A4 'starter-kg-inbox\.sh' "${adopt}" || true)"
    grep -qE '\|\| *\{|\|\| *exit|KGI_RC' <<< "${_call}" \
      || d2miss="${d2miss} chamador-não-lê-o-rc(adopt.md segue com a adoção)"
    grep -qE 'ABORTADO|exit 1' <<< "${_call}" \
      || d2miss="${d2miss} chamador-não-aborta"
    if [ -z "${d2miss}" ]; then
      record_pass "upstream-portal: (d2) o helper confere o próprio efeito (rc≠0 em DEST somente-leitura) e o chamador ABORTA"
    else
      record_fail "upstream-portal: (d2) fail-closed da fila na adoção" "fail-open em:${d2miss}"
    fi
  fi

  # ── (e) /meta:kg-inbox ROTEIA por papel — em TODOS os passos que decidem, não só no Passo 1 ─────
  #     Sinal de campo (2026-09-04): o comando parava em `role: adopted` e o
  #     adotante ficou sem mecanismo de selagem (forjou um /portal:selar local). A I3 é fronteira de
  #     REPO, não de papel: o dono sela a fila DO PRÓPRIO repo.
  #     ⚠️ A 1ª versão desta guarda olhava SÓ o Passo 1 — e passou verde com o Passo 3 ainda
  #     core-only ("Este conhecimento mora no CORE?" → REJEITAR contexto de adotante), isto é, com o
  #     adotante recusado no filtro SEGUINTE. Meia cura é o modo de falha desta perna; por isso a
  #     guarda varre os quatro passos que decidem, e não a porta de entrada.
  local kgi="${SCRIPT_DIR}/../commands/meta/kg-inbox.md"
  if [ ! -f "${kgi}" ]; then record_skip "upstream-portal: (e) kg-inbox.md ausente"; else
    local p1 p3 p4 p5 emiss=""
    p1="$(awk '/^## Passo 1/{f=1;next} /^## Passo 2/{f=0} f' "${kgi}")"
    p3="$(awk '/^## Passo 3/{f=1;next} /^## Passo 4/{f=0} f' "${kgi}")"
    p4="$(awk '/^## Passo 4/{f=1;next} /^## Passo 5/{f=0} f' "${kgi}")"
    p5="$(awk '/^## Passo 5/{f=1;next} /^## Saída|^Saída:/{f=0} f' "${kgi}")"
    # (e1) Passo 1 roteia e não recusa — ancorado na ESTRUTURA (a linha da tabela nomeia o que SELA)
    local row_adopted
    row_adopted="$(grep -E '^\|.*adopted' <<< "${p1}" | head -1)"
    [ -n "${row_adopted}" ] || emiss="${emiss} P1:sem-linha-de-tabela-para-adopted"
    grep -q 'kg-inbox' <<< "${row_adopted}" \
      || emiss="${emiss} P1:a-linha-de-adopted-não-nomeia-a-fila-que-sela"
    # recusa na forma DIRETIVA (linha com `→`, como as regras se escrevem aqui) co-ocorrendo com o papel
    local _dir1; _dir1="$(grep -E '→' <<< "${p1}" | grep -E 'adopted|hub' || true)"
    grep -qiE 'parar|pare|não sela|nao sela|não roda|nao roda|encerra|sem selar|abort' <<< "${_dir1}" \
      && emiss="${emiss} P1:recusa-por-papel-de-volta(forma diretiva)"
    grep -qiE 'este comando não roda aqui|não tem portão no core' <<< "${p1}" \
      && emiss="${emiss} P1:recusa-por-papel-de-volta(desvio para comando local)"
    grep -q 'adopted' <<< "${p1}" || emiss="${emiss} P1:não-menciona-adopted"
    grep -qiE 'rotear|roteamento' <<< "${p1}" || emiss="${emiss} P1:não-roteia"
    # (e1b) e NADA no comando pode autorizar selar grafo de OUTRO repo — a I3 não tem exceção por decreto
    local _alien; _alien="$(grep -iE 'outro repo|repo alheio|grafo alheio|qualquer árvore|qualquer arvore|de um vizinho' "${kgi}" || true)"
    grep -qiE 'permitid|autoriz|pode selar|pode viver|inclusive' <<< "${_alien}" \
      && emiss="${emiss} autoriza-selar-grafo-de-outro-repo(a I3 não abre por decreto)"
    # (e2) a invariante é sobre o ATO (o caminho do alvo), não sobre `meta.target` — campo que NENHUM
    #      produtor emite hoje (medido 2026-09-05: as 2 propostas reais do corpus não o trazem).
    grep -qi 'invariante é sobre o ATO' <<< "${p1}" \
      || emiss="${emiss} P1:invariante-ancorada-em-campo-fantasma(meta.target)"
    grep -qF 'GUARDA DO ATO' <<< "${p4}" || emiss="${emiss} P4:sem-guarda-do-ato(alvo dentro deste repo)"
    grep -qE 'pare e reporte' <<< "${p4}" || emiss="${emiss} P4:sem-parada-para-alvo-fora-do-repo"
    # (e3) Passo 3 pergunta por ESTE repo, trata os DOIS papéis, e o papel SÓ aparece na TABELA
    grep -qiE 'mora no CORE\?' <<< "${p3}" && emiss="${emiss} P3:filtro-ainda-core-only(mora no CORE?)"
    grep -qiE 'mora NESTE repo' <<< "${p3}" || emiss="${emiss} P3:fronteira-não-é-deste-repo"
    grep -q 'adopted' <<< "${p3}" || emiss="${emiss} P3:não-instancia-o-papel-adopted"
    # ESTRUTURAL: fora das linhas de tabela (`|…`), o Passo 3 não condiciona a decisão por papel
    # NENHUM — nem pelo negativo (`role: adopted` → recusa) nem pelo positivo (`role: source` → segue).
    # Quem roteia é a tabela; prosa que menciona um `role:` está decidindo, e é ali que a meia cura volta.
    local step
    for step in P3:"${p3}" P4:"${p4}" P5:"${p5}"; do
      local _prosa; _prosa="$(grep -vE '^\s*\|' <<< "${step#*:}" || true)"
      grep -qE 'role: *[a-z]|`adopted`|`hub`|`source`' <<< "${_prosa}" \
        && emiss="${emiss} ${step%%:*}:papel-fora-da-tabela(prosa condiciona a decisão por papel)"
    done
    # ...e a TABELA não é santuário: a linha do papel adotado tem de DIZER o que mora aqui
    local row3 col3
    row3="$(grep -E '^\s*\|.*adopted' <<< "${p3}" | head -1)"
    [ -n "${row3}" ] || emiss="${emiss} P3:sem-linha-de-tabela-para-adopted"
    col3="$(sed 's/\\|/§/g' <<< "${row3}" | awk -F'|' '{print $3}' | sed 's/^ *//; s/ *$//')"
    grep -qiE 'domínio deste repo|dominio deste repo' <<< "${col3}" \
      || emiss="${emiss} P3:a-linha-de-adopted-não-diz-o-que-mora-aqui(coluna='${col3}')"
    # ESTRUTURAL: o critério que MANDA SELAR não nomeia o core — nem no Passo 3 (c) nem no cabeçalho
    # do Passo 4. Foi ali que a meia cura sobreviveu à 3ª rodada, um bullet abaixo de onde foi curada.
    local _selar3; _selar3="$(grep -E 'SELAR' <<< "${p3}" || true)"
    grep -qiE 'do CORE|no CORE|pertence ao core' <<< "${_selar3}" \
      && emiss="${emiss} P3:o-critério-que-MANDA-selar-é-core-only"
    local _selar4; _selar4="$(grep -E '^\*\*SELAR\*\*' <<< "${p4}" || true)"
    grep -qiE 'do core|no core' <<< "${_selar4}" \
      && emiss="${emiss} P4:cabeçalho-do-SELAR-é-core-only"
    grep -qE 'SINAL REAL DESTE REPO' <<< "${p3}" || emiss="${emiss} P3:critério-positivo-não-é-deste-repo"
    local p2; p2="$(awk '/^## Passo 2/{f=1;next} /^## Passo 3/{f=0} f' "${kgi}")"
    grep -qiE 'cabeçalho é OPCIONAL|OPCIONAL, e num adotante' <<< "${p2}" \
      || emiss="${emiss} P2:cabeçalho-tratado-como-obrigatório(o produtor não é vendorizado)"
    # e nenhuma linha do Passo 3 junta o papel a um token de RECUSA
    local _pap3; _pap3="$(grep -E 'adopted|hub' <<< "${p3}" || true)"
    grep -qiE 'rejeit|_rejected|não sela|nao sela|nada sela|pertence ao core|só o core|so o core' <<< "${_pap3}" \
      && emiss="${emiss} P3:papel-co-ocorre-com-recusa(meia cura de volta)"
    # (e4) Passo 4 DESCOBRE o grafo-alvo em vez de presumir a convenção do core
    grep -qF "git ls-files '*.kg.yaml'" <<< "${p4}" || emiss="${emiss} P4:alvo-não-descoberto(git ls-files '*.kg.yaml')"
    grep -qE "^[^#]*docs/onion/graph/<slug>\.kg\.yaml" <<< "${p4}" \
      && ! grep -qi 'convenção DESTE repo' <<< "${p4}" && emiss="${emiss} P4:alvo-hard-coded-na-convenção-do-core"
    # (e5) Passo 5 carimba nó DESTE repo (no adotante não existe Q_SEALING_NO_MECHANISM)
    grep -qiE 'deste[[:space:]\n]*repo|num adotante' <<< "${p5}" || emiss="${emiss} P5:nó-a-carimbar-só-do-core"
    local _core5; _core5="$(grep -iE 'core' <<< "${p5}" || true)"
    grep -qiE 'pule|não há|nao ha|encerre|só a sessão|so a sessao|apenas a sessão' <<< "${_core5}" \
      && emiss="${emiss} P5:dispensa-o-fecho-por-papel(core juntado a uma dispensa)"
    grep -q 'verified_at' <<< "${p5}" && grep -q 'verified_against' <<< "${p5}" \
      || emiss="${emiss} P5:manda-carimbar-done-sem-exigir-verificação(REGRA 49 reprova HARD depois; o radar é cego a isso)"
    grep -qiE 'lint-artifacts|gate do repo' <<< "${p5}" \
      || emiss="${emiss} P5:fecha-só-com-o-radar(que detecta frescor e PARA AÍ)"
    if [ -z "${emiss}" ]; then
      record_pass "upstream-portal: (e) /meta:kg-inbox roteia por papel nos 4 passos que decidem, com a invariante no ATO (alvo dentro deste repo)"
    else
      record_fail "upstream-portal: (e) roteamento por papel no kg-inbox" "o comando roteia pela metade —${emiss}"
    fi
  fi
}
_family run_upstream_portal_fixes_selftests

# Predicado ÚNICO de fixture (achado de campo da adoção greenfield de 2026-09-05): seis consumidores
# repetiam `grep -v '/fixtures/'` e o `__fixtures__/` do Vitest ESCAPAVA — 5 grafos deliberadamente
# inválidos de um adotante viraram 5 HARD da REGRA 52 no dia 1 dele, e as saídas eram apagar o teste
# ou desligar a guarda. Aqui se prova (a) o predicado, (b) que os SEIS consumidores o usam, e (c) que
# a isenção não virou fail-open por substring.
run_kg_fixture_paths_selftests() {
  local h="${SCRIPT_DIR}/kg-fixture-paths.sh"
  if [ ! -f "${h}" ]; then record_skip "kg-fixture-paths: helper ausente"; return; fi

  # (a) o selftest do próprio predicado (5 convenções isentas + 4 armadilhas que NÃO se isentam)
  local out
  out="$(bash "${h}" --selftest 2>&1 || true)"
  if grep -q '^kg-fixture-paths selftest: OK' <<< "${out}"; then
    record_pass "kg-fixture-paths: (a) predicado cobre a CLASSE de convenções e recusa as armadilhas de substring"
  else
    record_fail "kg-fixture-paths: (a) predicado" "$(printf '%s' "${out}" | grep '✗' | head -3 | tr '\n' ' ')"
  fi

  # (b) o achado de campo, verbatim: a convenção Vitest tem de ser isentada e a do core continuar isentada
  local miss=""
  bash "${h}" --is-fixture 'packages/kg/src/__fixtures__/orphan.kg.yaml' || miss="${miss} __fixtures__(Vitest)"
  bash "${h}" --is-fixture '.claude/validation/fixtures/kg-drive/deadlock.kg.yaml' || miss="${miss} fixtures(core)"
  # e o fail-open que um `grep -v fixtures` ingênuo abriria
  bash "${h}" --is-fixture 'docs/onion/graph/fixtures-do-produto.kg.yaml' && miss="${miss} isentou-por-NOME-de-arquivo" || true
  bash "${h}" --is-fixture 'docs/mixtures/y.kg.yaml' && miss="${miss} isentou-por-SUBSTRING(mixtures)" || true
  if [ -z "${miss}" ]; then
    record_pass "kg-fixture-paths: (b) __fixtures__ do Vitest isento, e nome-de-arquivo/substring NÃO isentam"
  else
    record_fail "kg-fixture-paths: (b) alcance da isenção" "falhou em:${miss}"
  fi

  # (c) TODOS os consumidores passam pelo predicado — nenhum ficou com o grep próprio para envelhecer
  # ⚠️ A lista de consumidores é DERIVADA do corpus, não digitada — e o caminho é RELATIVO AO REPO,
  #    sem `basename`: a 1ª derivação mangleava o path e testava `${SCRIPT_DIR}/<base>`, que só acha
  #    `validation/`, então os consumidores em `utils/` eram descartados EM SILÊNCIO e a mensagem
  #    ainda dizia "os 5". Lista que envelhece é a classe que este predicado combate; e derivação que
  #    descarta calado é a mesma classe um nível acima.
  local c cmiss="" _root2 _n_cons=0
  _root2="$(cd "${SCRIPT_DIR}/../.." && pwd)"
  while IFS= read -r c; do
    [ -n "${c}" ] || continue
    # manifesto LISTA o predicado no VALIDATION[] (é o que faz o bundle não nascer morto) — não o
    # CONSOME; e o próprio predicado e a bancada estão fora do escopo por construção.
    case "${c}" in */kg-fixture-paths.sh|*/lint-selftest.sh|*.manifest.sh) continue ;; esac
    [ -f "${_root2}/${c}" ] || { cmiss="${cmiss} ${c}:derivado-mas-inexistente"; continue; }
    _n_cons=$(( _n_cons + 1 ))
    # USO, não MENÇÃO: os consumidores todos citam o predicado no comentário da cura, então casar a
    # menção deixaria um regredir 100% com a bancada verde (medido pelo Elenxo em 2026-09-05).
    # ⚠️ NADA DE VEREDITO ATRAVÉS DE PIPE. `grep arquivo | grep -q` é corrida: o leitor fecha no 1º
    #    match, o escritor toma EPIPE e sob `set -o pipefail` o pipeline devolve FALHA com o padrão
    #    PRESENTE. Foi a classe que EU curei em 496 sítios nesta sessão e reintroduzi aqui: local
    #    1054/0, CI de 2 cores reprovando 1 caso. Conteúdo em VARIÁVEL, veredito por here-string.
    local _code; _code="$(grep -vE '^[[:space:]]*#' "${_root2}/${c}" || true)"
    grep -qF 'bash "${_KFP}"' <<< "${_code}" || grep -qF 'kg-fixture-paths.sh" --' <<< "${_code}" \
      || cmiss="${cmiss} ${c}:não-INVOCA-o-predicado(menção em comentário não conta)"
    # e nenhuma reintrodução do grep próprio, nas 3 grafias que escapavam da 1ª versão (aspas
    # simples, aspas duplas, alternação -E). Ancorado no PADRÃO, não na pontuação.
    grep -qE "grep -v[a-zA-Z]*[[:space:]]+[\"']?[^\"']*/fixtures/|-not -path .\*/fixtures/\*|case[^)]*\*/fixtures/\*\)" <<< "${_code}" \
      && cmiss="${cmiss} ${c}:AINDA-tem-grep-próprio"
  # ⚠️ SÓ `.sh` — consumidor é quem EXECUTA, e um arquivo de DADOS que cita o nome não executa nada.
  # Medido em 2026-09-14: ao alargar o detector da classe EPIPE, `kg-fixture-paths.sh` entrou no
  # `pipe-verdict-baseline.txt` (formato `<arquivo><TAB><contagem>`), e este `grep -rl` tomou o
  # BASELINE por consumidor — exigindo que um `.txt` invocasse um predicado. Cascata de guardas: um
  # detector alargado alimenta um baseline, o baseline vira "menção", e a guarda vizinha lê menção
  # como uso. É a mesma classe de sempre (a enumeração por string não distingue DADO de CÓDIGO), e
  # a cura é a de sempre: restringir pela FORMA do que pode ser consumidor, não pela string.
  done < <( (cd "${_root2}" && grep -rl --include='*.sh' 'kg-fixture-paths\.sh' .claude/validation .claude/utils 2>/dev/null) | sort -u )
  # Piso ANCORADO nos sítios onde o predicado é load-bearing, não num número digitado (o `>=7` que
  # estava aqui passou a reprovar o estado CORRETO quando o 7º sítio foi revertido — e só apareceu na
  # suíte completa, porque isolada eu a rodara antes). O seed é o crítico: ali a isenção incompleta
  # CANCELA a semente do KG, em vez de afrouxar um gate.
  local _obrig _falta=""
  for _obrig in .claude/utils/adopt/seed-adoption-graph.sh .claude/validation/kg-radar-integrity.sh \
                .claude/validation/kg-trace-resolve.sh .claude/validation/kg-backlog-project.sh \
                .claude/validation/kg-corpus-grep.sh .claude/validation/kg-verification-coverage.sh; do
    (cd "${_root2}" && grep -q 'kg-fixture-paths\.sh' "${_obrig}" 2>/dev/null) || _falta="${_falta} ${_obrig}"
  done
  [ -z "${_falta}" ] || cmiss="${cmiss} sítio-obrigatório-sem-o-predicado:${_falta}"
  if [ -z "${cmiss}" ]; then
    record_pass "kg-fixture-paths: (c) os ${_n_cons} consumidores DERIVADOS (6 obrigatórios conferidos por nome) invocam o predicado e nenhum guardou o grep próprio"
  else
    record_fail "kg-fixture-paths: (c) consumidores" "seis listas, um vocabulário —${cmiss}"
  fi

  # (d2) FAIL-CLOSED e caminho ABSOLUTO — a classe que eu introduzi ao ligar os consumidores e que só
  #      o mutante de VACUIDADE do kg-trace pegou (o lint passou 0 HARD): `$(dirname "${BASH_SOURCE[0]}")`
  #      no ponto de uso morre depois de um `cd`, o `|| true` engole o erro, e a varredura fica VAZIA —
  #      verde por vacuidade em qualquer repo. Duas exigências, uma por sítio: caminho resolvido ANTES
  #      de qualquer cd, e ausência do predicado = exit != 0, nunca silêncio.
  local c fmiss=""
  for c in kg-radar-integrity.sh kg-corpus-grep.sh kg-trace-resolve.sh kg-backlog-project.sh kg-verification-coverage.sh; do
    [ -f "${SCRIPT_DIR}/${c}" ] || continue
    grep -q '_KFP="\$(cd "\$(dirname "\${BASH_SOURCE\[0\]}")" && pwd)/kg-fixture-paths.sh"' "${SCRIPT_DIR}/${c}" \
      || fmiss="${fmiss} ${c}:caminho-não-absoluto(morre após cd)"
    grep -qE '\[ -f "\$\{_KFP\}" \] \|\| \{.*exit 2' "${SCRIPT_DIR}/${c}" \
      || fmiss="${fmiss} ${c}:ausência-do-predicado-não-é-fail-closed"
    grep -q 'dirname "${BASH_SOURCE\[0\]}")/kg-fixture-paths.sh"' "${SCRIPT_DIR}/${c}" \
      && fmiss="${fmiss} ${c}:AINDA-resolve-no-ponto-de-uso"
  done
  # e a prova por COMPORTAMENTO: sem o predicado ao lado, o consumidor sai != 0 em vez de "nada a ver"
  local sb2 rc2=0
  sb2="$(mktemp -d)"; cp "${SCRIPT_DIR}/kg-trace-resolve.sh" "${sb2}/t.sh" 2>/dev/null || true
  if [ -f "${sb2}/t.sh" ]; then
    bash "${sb2}/t.sh" "${SCRIPT_DIR}/../.." --format tsv >/dev/null 2>&1 || rc2=$?
    [ "${rc2}" -ne 0 ] || fmiss="${fmiss} comportamento:sem-o-predicado-saiu-0(fail-open)"
  fi
  rm -rf "${sb2}"
  if [ -z "${fmiss}" ]; then
    record_pass "kg-fixture-paths: (d2) predicado resolvido em caminho ABSOLUTO e ausência é fail-closed (medido por execução)"
  else
    record_fail "kg-fixture-paths: (d2) resolução do predicado" "verde-por-vacuidade em:${fmiss}"
  fi

  # (d3) MUDEZ é irmã da AUSÊNCIA — e o (d2) só cobria a ausência. Sem branch `*)` no `case`, uma flag
  #      com typo caía fora, o script saía 0 com STDOUT VAZIO, e o consumidor via ZERO grafos: verde
  #      por vacuidade por UM caractere (medido 2026-09-05). E o par obrigatório: a cura da mudez
  #      introduz `exit` num arquivo que TAMBÉM é biblioteca (`source … && kg_graphs`, uso documentado),
  #      logo exige guarda de sourcing — sem ela o `source` sem args morria com rc=2 (também medido).
  local mmiss="" rcm=0 rcs=0 nsrc=0
  printf 'a/__fixtures__/x.kg.yaml\n' | bash "${h}" --filtre >/dev/null 2>&1 || rcm=$?
  [ "${rcm}" -eq 2 ] || mmiss="${mmiss} flag-com-typo-não-recusa(rc=${rcm}, saída vazia = varredura vazia)"
  rcm=0; bash "${h}" >/dev/null 2>&1 || rcm=$?
  [ "${rcm}" -eq 2 ] || mmiss="${mmiss} sem-argumento-não-recusa(rc=${rcm})"
  nsrc="$(bash -c "source '${h}' && kg_graphs '${SCRIPT_DIR}/../..'" 2>/dev/null | grep -c . || true)"
  bash -c "source '${h}' && kg_graphs '${SCRIPT_DIR}/../..' >/dev/null" >/dev/null 2>&1 || rcs=$?
  { [ "${rcs}" -eq 0 ] && [ "${nsrc}" -gt 0 ]; } \
    || mmiss="${mmiss} source-quebrado(rc=${rcs}, ${nsrc} grafos — a cura da mudez precisa de guarda de sourcing)"
  if [ -z "${mmiss}" ]; then
    record_pass "kg-fixture-paths: (d3) mudez recusa (typo e sem-arg → exit 2) E o uso como biblioteca (source) segue vivo"
  else
    record_fail "kg-fixture-paths: (d3) mudez e sourcing" "verde-por-vacuidade ou biblioteca quebrada em:${mmiss}"
  fi

  # (d) a isenção é AUDITÁVEL: --list-exempt e --graphs particionam o acervo sem perder nem duplicar
  # ⚠️ UM ROOT SÓ nos três: a 1ª versão comparava `git ls-files` relativo ao CWD contra `--graphs`
  #    com ROOT absoluto — rodada de `docs/` a conta dava 90 vs 121 e o caso FALHAVA. Flaky que EU
  #    introduzi; a bancada não faz `cd` para o REPO_ROOT, então CWD-dependência é defeito.
  local n_all n_g n_x _root
  _root="$(cd "${SCRIPT_DIR}/../.." && pwd)"
  n_all="$( (cd "${_root}" && git ls-files '*.kg.yaml' 2>/dev/null) | grep -c . || true)"
  n_g="$(bash "${h}" --graphs "${_root}" | grep -c . || true)"
  n_x="$(bash "${h}" --list-exempt "${_root}" | grep -c . || true)"
  if [ "$(( n_g + n_x ))" -eq "${n_all}" ] && [ "${n_all}" -gt 0 ]; then
    record_pass "kg-fixture-paths: (d) partição exata do acervo (${n_g} julgados + ${n_x} isentos = ${n_all})"
  else
    record_fail "kg-fixture-paths: (d) partição do acervo" "julgados=${n_g} + isentos=${n_x} != total=${n_all} — isenção que não fecha a conta esconde grafo"
  fi
}
_family run_kg_fixture_paths_selftests

# Aviso de hook roteado pelo ARTEFATO, não pelo papel (sinal de campo de um repo PRÉ-ADOÇÃO,
# 2026-09-05): o guard mandava ler o check `onion-review-verdict` num repo que não o tem — texto certo,
# contexto errado, e aviso que manda caçar fantasma gasta a confiança do canal.
run_hook_reviewer_context_selftests() {
  local h="${SCRIPT_DIR}/../hooks/bash-empty-result-guard.sh"
  if [ ! -f "${h}" ]; then record_skip "hook-reviewer-context: guard ausente"; return; fi
  local core="${SCRIPT_DIR}/../.." out miss=""

  # (a) repo COM o workflow do revisor → a mensagem que cita o check
  out="$(printf '{"tool_input":{"command":"gh pr merge 1"}}' | CLAUDE_PROJECT_DIR="${core}" bash "${h}" 2>&1 || true)"
  grep -q 'MERGE-SEM-FONTE-LIDA' <<< "${out}" || miss="${miss} core:não-cita-o-check"

  # (b) repo SEM o workflow → a mensagem que NÃO manda procurar o check
  local sb; sb="$(mktemp -d)"; git -C "${sb}" init -q 2>/dev/null
  out="$(printf '{"tool_input":{"command":"gh pr merge 1"}}' | CLAUDE_PROJECT_DIR="${sb}" bash "${h}" 2>&1 || true)"
  grep -q 'MERGE-SEM-REVISOR' <<< "${out}" || miss="${miss} sem-revisor:mensagem-errada"
  grep -q 'onion-review-verdict.*em .gh pr checks' <<< "${out}" && miss="${miss} sem-revisor:AINDA-manda-procurar-o-check"

  # (c) o predicado é o ARTEFATO, não o STAMP: um repo com stamp e SEM workflow não pode citar o check
  #     (é o caso do adotante recém-adotado — e o CORE não tem stamp, então testar papel inverteria os dois)
  mkdir -p "${sb}/.claude"; printf 'role: adopted\n' > "${sb}/.claude/.onion-version"
  out="$(printf '{"tool_input":{"command":"gh pr merge 1"}}' | CLAUDE_PROJECT_DIR="${sb}" bash "${h}" 2>&1 || true)"
  grep -q 'MERGE-SEM-REVISOR' <<< "${out}" || miss="${miss} adotado-sem-workflow:voltou-a-citar-o-check(predicado é papel, não artefato)"
  rm -rf "${sb}"

  if [ -z "${miss}" ]; then
    record_pass "hook-reviewer-context: o aviso roteia pelo ARTEFATO (workflow do revisor), cobrindo core · adotado-sem-workflow · pré-adoção"
  else
    record_fail "hook-reviewer-context: roteamento do aviso" "manda caçar fantasma em:${miss}"
  fi
}
_family run_hook_reviewer_context_selftests

# O BUNDLE fecha o grafo de dependências? (achado do Elenxo, 2026-09-05, medido dentro do host):
# o `kg-backlog-project` empacotado passou a resolver `kg-fixture-paths.sh` ao lado e ABORTAR sem ele
# (fail-closed correto) — e o assembler ACEITOU montar, porque a guarda de dependência dele só olhava
# `lib/`. Dep IRMÃO em `validation/` era invisível: o plugin público nascia MORTO no consumidor.
# É a classe que o próprio predicado combate — guarda de lista falha pelo VOCABULÁRIO — cometida no
# mecanismo que deveria proteger contra ela.
run_bundle_dep_closure_selftests() {
  local asm="${SCRIPT_DIR}/../utils/marketplace/assemble-plugin.sh"
  local man="${SCRIPT_DIR}/../utils/marketplace/verticals/onion.manifest.sh"
  if [ ! -f "${asm}" ] || [ ! -f "${man}" ]; then record_skip "bundle-dep: assembler/manifesto ausente"; return; fi
  local root="${SCRIPT_DIR}/../.."

  # (a) o manifesto VIGENTE fecha o grafo — o assembler monta sem acusar dependência ausente
  local d rc=0 out
  d="$(mktemp -d)"
  out="$(bash "${asm}" "${man}" "${root}" "${d}" 2>&1 || true)"
  bash "${asm}" "${man}" "${root}" "${d}" >/dev/null 2>&1 || rc=$?
  if [ "${rc}" -eq 0 ] && ! grep -q 'nao fecha o grafo de dependencias' <<< "${out}"; then
    record_pass "bundle-dep: (a) o manifesto vigente fecha o grafo de dependências (assembler monta limpo)"
  else
    record_fail "bundle-dep: (a) manifesto vigente" "rc=${rc}; $(grep 'precisa de' <<< "${out}" | head -2 | tr '\n' ' ')"
  fi

  # (b) COMPORTAMENTO no host: o consumidor empacotado roda em vez de abortar por dep ausente
  local rp=0 op
  if [ -d "${d}/validation" ]; then
    local sb; sb="$(mktemp -d)"; mkdir -p "${sb}/docs/onion/graph"
    printf 'meta:\n  id: x\nnodes:\n  - id: A\n    node_type: decision\n    status: open\nedges: []\n' > "${sb}/docs/onion/graph/x.kg.yaml"
    ( cd "${sb}" && git init -q && git add -A && git -c user.email=t@t -c user.name=t commit -qm x ) >/dev/null 2>&1
    op="$( cd "${sb}" && CLAUDE_PLUGIN_ROOT="${d}" bash "${d}/validation/kg-backlog-project.sh" --check 2>&1 || true )"
    grep -q 'predicado de fixture ausente' <<< "${op}" && rp=1
    rm -rf "${sb}"
  fi
  if [ "${rp}" -eq 0 ]; then
    record_pass "bundle-dep: (b) o consumidor EMPACOTADO acha a dependência dentro do host (não nasce morto)"
  else
    record_fail "bundle-dep: (b) bundle morto no host" "o script empacotado abortou por dependência ausente — o predicado não está no VALIDATION[] do manifesto"
  fi

  # (c) MUTANTE: tirar a dep do manifesto tem de fazer o ASSEMBLER acusar — nomeando o arquivo certo
  local mman rcm=0 outm
  mman="$(mktemp)"; grep -v 'kg-fixture-paths.sh' "${man}" > "${mman}"
  local d2; d2="$(mktemp -d)"
  outm="$(bash "${asm}" "${mman}" "${root}" "${d2}" 2>&1 || true)"
  bash "${asm}" "${mman}" "${root}" "${d2}" >/dev/null 2>&1 || rcm=$?
  if [ "${rcm}" -ne 0 ] && grep -q 'precisa de .*kg-fixture-paths\.sh' <<< "${outm}"; then
    record_pass "bundle-dep: (c) (MUT) dep IRMÃO fora do manifesto → assembler RECUSA nomeando o arquivo (não só lib/)"
  else
    record_fail "bundle-dep: (c) (MUT) dep irmão" "assembler aceitou (rc=${rcm}) — a guarda voltou a ver só lib/ e o bundle nasceria morto"
  fi
  # (d) e a guarda NÃO pode reprovar por PROSA: citação em comentário (`graph.sh:164`) não é dependência
  if grep -q 'precisa de .*graph\.sh' <<< "${outm}"; then
    record_fail "bundle-dep: (d) guarda lê prosa" "acusou graph.sh, que aparece só em CITAÇÃO de comentário — fail-closed excessivo (a 1ª generalização fez isso)"
  else
    record_pass "bundle-dep: (d) citação em comentário NÃO conta como dependência (a guarda lê invocação)"
  fi
  rm -rf "${d}" "${d2}"; rm -f "${mman}"
}
_family run_bundle_dep_closure_selftests









# ---------------------------------------------------------------------------
# O harness testando a SI MESMO — os três desfechos não podem colapsar em dois
#
# Origem: sinal de campo 2026-07-25 (adotante). Um runner que só distingue "lançar" de
# "não lançar" soma o `skip` em `passed`; um ambiente sem o serviço produz o MESMO
# "N passed" de um ambiente saudável. Aqui isso valia para 32 sítios.
#
# O aceite de uma guarda nascida de auditoria não é "roda e passa" — é "ela pega o caso
# que a motivou?" (architecture-challenges.md §1.3). O caso é a REINTRODUÇÃO do skip-como-
# ✓, e (a) o pega POR CONSTRUÇÃO: guard de tooling na mesma linha de record_pass reprova.
# ---------------------------------------------------------------------------

run_selftest_outcomes_selftests() {
  local me="${SCRIPT_DIR}/lint-selftest.sh"
  [ -f "${me}" ] || { record_fail "selftest-outcomes" "não achei a mim mesmo: ${me}"; return; }
  local n out rc block

  # (a) ANTI-DRIFT: nenhum guard de tooling/import pode registrar record_pass.
  n="$(grep -cE '(command -v [a-z0-9]+|import yaml)[^#]*record_pass' "${me}" || true)"
  if [ "${n}" = 0 ]; then
    record_pass "selftest-outcomes: (a) nenhum guard de tooling soma em ✓ (skip-como-passe não volta)"
  else record_fail "selftest-outcomes: (a) anti-drift" "${n} guard(s) de tooling registram record_pass — falso-verde por vacuidade reintroduzido"; fi

  # (b) o terceiro desfecho tem CONTADOR PRÓPRIO (não é apelido de record_pass).
  if grep -q '^record_skip()' "${me}" && grep -q 'SKIP=\$((SKIP + 1))' "${me}"; then
    record_pass "selftest-outcomes: (b) record_skip existe com contador próprio"
  else record_fail "selftest-outcomes: (b)" "record_skip ausente ou sem contador próprio"; fi

  # (c) FUNCIONAL — extrai o trio real de record_* e confere a aritmética: ⊘ nunca vira ✓.
  block="$(sed -n '/^record_pass()/,/^record_skip()/p' "${me}")"
  out="$(bash -c 'PASS=0; FAIL=0; SKIP=0; FAILED_CASES=(); SKIPPED_CASES=()
'"${block}"'
record_skip a >/dev/null; record_skip b >/dev/null; record_pass c >/dev/null
printf "%s/%s" "${PASS}" "${SKIP}"' 2>/dev/null || true)"
  if [ "${out}" = "1/2" ]; then
    record_pass "selftest-outcomes: (c) 2 skips + 1 pass ⇒ PASS=1 SKIP=2 (⊘ não soma em ✓)"
  else record_fail "selftest-outcomes: (c) aritmética" "esperava PASS/SKIP='1/2', veio '${out}'"; fi

  # (d)+(e) FUNCIONAL — o bloco REAL de sumário, com contadores forjados.
  block="$(sed -n '/^echo "=== Sumário do auto-teste de guardas ==="/,$p' "${me}")"
  # (d) STRICT=1 + skip ⇒ exit 1 (asserção de capacidade — o modo do CI).
  rc=0; out="$(bash -c 'PASS=3; FAIL=0; SKIP=2; FAILED_CASES=(); SKIPPED_CASES=(x y); STRICT=1
'"${block}"'' 2>&1)" || rc=$?
  if [ "${rc}" -eq 1 ] && grep -q 'FALHOU (STRICT)' <<< "${out}"; then
    record_pass "selftest-outcomes: (d) STRICT=1 + skip ⇒ exit 1 (CI não aceita 'não verifiquei')"
  else record_fail "selftest-outcomes: (d) strict" "esperava exit 1 + 'FALHOU (STRICT)'; rc=${rc} out=${out}"; fi

  # (e) sem STRICT ⇒ exit 0, MAS os pulados aparecem: gracioso não pode ser silencioso.
  rc=0; out="$(bash -c 'PASS=3; FAIL=0; SKIP=2; FAILED_CASES=(); SKIPPED_CASES=(x y); STRICT=0
'"${block}"'' 2>&1)" || rc=$?
  if [ "${rc}" -eq 0 ] && grep -q 'NÃO VERIFICADOS' <<< "${out}" \
     && grep -q 'Pularam  : 2' <<< "${out}"; then
    record_pass "selftest-outcomes: (e) sem STRICT ⇒ exit 0 com os ⊘ VISÍVEIS (gracioso ≠ silencioso)"
  else record_fail "selftest-outcomes: (e) visibilidade" "esperava exit 0 + contagem/lista de pulados; rc=${rc} out=${out}"; fi

  # (f) ISOLAMENTO DO ENV DE HOOK. `git commit` exporta GIT_DIR/GIT_INDEX_FILE; herdados,
  # envenenam toda sandbox git da suíte (medido: abort no caso 93 de 472, anunciado pelo
  # hook como "falhou"). Usa o preâmbulo REAL do script, com GIT_DIR envenenado.
  local pre; pre="$(grep -m1 '^unset GIT_DIR' "${me}")"
  if [ -z "${pre}" ]; then
    record_fail "selftest-outcomes: (f) env de hook" "o preâmbulo 'unset GIT_DIR …' sumiu — o pre-commit volta a abortar no meio"
  elif (cd "${REPO_ROOT}" && GIT_DIR=/nao/existe GIT_INDEX_FILE=/nao/existe \
        bash -c "${pre}"'; git rev-parse --show-toplevel' >/dev/null 2>&1); then
    # (MUT) sem o unset, o MESMO comando tem de quebrar — senão o teste não prova nada.
    if (cd "${REPO_ROOT}" && GIT_DIR=/nao/existe GIT_INDEX_FILE=/nao/existe \
        git rev-parse --show-toplevel >/dev/null 2>&1); then
      record_fail "selftest-outcomes: (f) MUT" "GIT_DIR envenenado NÃO quebra o git — o caso (f) é vacuidade, não prova"
    else
      record_pass "selftest-outcomes: (f) env de hook neutralizado + (MUT) sem o unset o git quebra — a guarda é load-bearing"
    fi
  else record_fail "selftest-outcomes: (f) env de hook" "GIT_DIR envenenado sobrevive ao preâmbulo"; fi
}
_family run_selftest_outcomes_selftests
_family run_shell_pipefail_robustness_selftests
_family run_aside_router_selftests

# Modo kg-view — REGRA 31: lente derivada, determinística e em paridade com o motor.
_family run_vendor_scrub_selftests
